INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2024-v0-001', '291f516814800bc6f38c18daaa87f903358c5c04', 2024, 0, 1, false, false, 'Endocrinología', NULL, 'Hombre de 56 años con un tumor palpable en el lado izquierdo del cuello móvil a la deglución. Se acompaña de disfagia y disfonía. Tiene historia familiar de tumores endocrinos. ¿ Cuál de los siguientes es el diagnóstico anatomopatológico más probable de la lesión que aparece en la imagen ?:', '[{"position": 1, "text": "Carcinoma papilar de tiroides."}, {"position": 2, "text": "Carcinoma medular de tiroides."}, {"position": 3, "text": "Linfoma difuso de célula grande."}, {"position": 4, "text": "Sarcoma sinovial."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/24/image_1.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-002', 'a3cf570811aae584f649ad7a3a33e9fcebf40b9d', 2024, 0, 2, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Paciente que ha sufrido un accidente de bicicleta con traumatismo facial directo sobre la región anterior de la mandíbula. Se realiza la tomografía computarizada (TC) de la imagen que confirma una:', '[{"position": 1, "text": "Fractura panfacial tipo Lefort I."}, {"position": 2, "text": "Fractura panfacial tipo Lefort II."}, {"position": 3, "text": "Fractura mandibular bicondilea inestable."}, {"position": 4, "text": "Fractura mandibular bilateral en ramas horizontales inestable."}]'::jsonb, 4, 4, 'definitiva', NULL, true, 'images/24/image_2.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-003', '5d98b307bce171dc7504bd1d1f529a1fa84b9059', 2024, 0, 3, false, false, 'Dermatología', NULL, 'Hombre de 75 años, sin antecedentes personales de interés, agricultor jubilado, que acude a la consulta refiriendo que en los últimos 10 años ha notado la aparición progresiva en cuero cabelludo (es calvo desde hace años) de pequeñas placas eritematosas, muchas de ellas con descamación y rasposas al tacto, siendo la mayoría asintomáticas, si bien alguna le molesta al tacto. Ante este cuadro clínico y la imagen ¿cuál de los siguientes sería el diagnóstico ?:', '[{"position": 1, "text": "Dermatitis seborreica."}, {"position": 2, "text": "Queratosis actínica."}, {"position": 3, "text": "Liquen nitidus."}, {"position": 4, "text": "Psoriasis."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/24/image_3.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-004', 'd8022b45492efb14f785503a4c33b4cb4a368b69', 2024, 0, 4, false, false, 'Dermatología', NULL, 'Hombre de 25 años sin antecedentes personales de interés que acude a la consulta de dermatología porque desde hace 4 semanas nota la aparición de unas pápulas aterciopeladas en la zona perianal (imagen), asintomáticas, que van aumentado en número poco a poco. ¿ Cuál de los siguientes diagnósticos es más probable ?:', '[{"position": 1, "text": "Condiloma lata."}, {"position": 2, "text": "Molluscum contagiosum."}, {"position": 3, "text": "Condiloma acuminado."}, {"position": 4, "text": "Liquen plano."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_4.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-005', '9caec8a963a166aad0d18598fabd11af153ed154', 2024, 0, 5, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer de 32 años con diagnóstico reciente de carcinoma ductal infiltrante G3 de mama izquierda, fenotipo triple negativo. Se muestran las imágenes de la PET-TC con 18F-FDG con proyección de intensidad máxima (MIP) y cortes axiales a nivel de mama y axila. De las siguientes afirmaciones, señale la correcta:', '[{"position": 1, "text": "El tratamiento electivo de inicio es tumorectomía y biopsia selectiva de ganglio centinela."}, {"position": 2, "text": "El tratamiento electivo de inicio es mastectomía y biopsia selectiva del ganglio centinela."}, {"position": 3, "text": "Se visualiza afectación en mama izquierda y axilar ipsilateral."}, {"position": 4, "text": "Se visualiza afectación en mama izquierda, axila izquierda y metástasis a distancia."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_5.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-006', '9faca88e5eb83f612afbbfd5f0fe3e2b0c9c7ae0', 2024, 0, 6, false, false, 'Neurología y Neurocirugía', NULL, 'Mujer de 27 años, sin antecedentes de interés, que acude a urgencias por episodios transitorios de pérdida de visión bilateral de 15 segundos de duración, cefalea al despertarse y acúfenos de unas semanas de evolución. Tiene un IMC de 29. La RM craneal descarta lesiones ocupantes de espacio. Con la clínica referida y la imagen de fondo de ojo ¿cuál de las siguientes afirmaciones es correcta ?:', '[{"position": 1, "text": "La pérdida de peso no es eficaz en esta situación."}, {"position": 2, "text": "La acetazolamida y la furosemida son fármacos empleados habitualmente."}, {"position": 3, "text": "Se debe realizar una punción lumbar antes de la prueba de imagen."}, {"position": 4, "text": "Los corticoides orales se usan ampliamente en el manejo de esta entidad."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/24/image_6.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-007', '2faee5ba75d61ef6e69ca944986da25198c73771', 2024, 0, 7, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Mujer de 57 años que consulta por hipoacusia derecha neurosensorial progresiva y acúfenos. En relación con la imagen mostrada, indique de qué exploración se trata y el diagnóstico más probable:', '[{"position": 1, "text": "RM sin contraste. Meningioma."}, {"position": 2, "text": "TC con contraste. Tumor epidermoide."}, {"position": 3, "text": "RM con contraste. Tumor glial."}, {"position": 4, "text": "RM con contraste. Schwannoma vestibular."}]'::jsonb, 4, 4, 'definitiva', NULL, true, 'images/24/image_7.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-008', '91a35b85c61605345fa3feb79bc035d9a62546af', 2024, 0, 8, false, false, 'Neurología y Neurocirugía', NULL, 'Hombre de 84 años con antecedentes de hipertensión arterial, dislipemia e infarto agudo de miocardio. Acude a urgencias por deterioro cognitivo rapidamente progresivo, amnesia, inestabilidad para la marcha y hemianopsia homónima izquierda. Se le realiza la siguiente TC craneal. Señale cuál es el diagnóstico más probable ante el hallazgo mostrado:', '[{"position": 1, "text": "Absceso cerebral secundario a otitis media aguda derecha."}, {"position": 2, "text": "Trombosis venosa del seno sigmoide derecho."}, {"position": 3, "text": "Infarto isquémico agudo en territorio de arteria cerebral posterior derecha."}, {"position": 4, "text": "Neoplasia cerebral de origen glial con edema perilesional asociado."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_8.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-009', 'aa455d856d3f81830d093bd2809ec9c90c9fdce8', 2024, 0, 9, false, false, 'Aparato Digestivo', NULL, 'Hombre de 72 años con diagnóstico de carcinoma de cavidad oral intervenido hace tres meses con resección completa, en tratamiento con quimioterapia, portador de gastrostomía endoscópica percutánea profiláctica, que acude a urgencias por dolor y distensión abdominal de tres días de evolución, intolerancia oral y ausencia de deposiciones. Se realiza la TC abdominopélvica con contraste intravenoso que se muestra en la imagen. ¿ Cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Obstrucción intestinal secundaria a neoplasia estenosante de colon descendente."}, {"position": 2, "text": "Obstrucción intestinal de causa extrínseca por carcinomatosis peritoneal."}, {"position": 3, "text": "Obstrucción intestinal por migración e impactación de la sonda de gastrostomía."}, {"position": 4, "text": "Obstrucción funcional o íleo pseudoobstructivo por fármacos."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_9.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-010', '898d55f0016460ba08e89bf130060ef0f978e130', 2024, 0, 10, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 61 años, que recibió un trasplante alogénico haploidéntico hace 20 meses por linfoma no Hodgkin T, en respuesta completa, que consulta por un síndrome febril desde hace 72 horas con tos y expectoración blanquecina y disnea progresiva a moderados esfuerzos. Refiere astenia desde hace un mes y medio. Se realiza la TC torácica que se muestra en la imagen. ¿ Cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Neumonía por Mycobacterium tuberculosis."}, {"position": 2, "text": "Neumonía por Aspergillus."}, {"position": 3, "text": "Neumonía por Streptococcus pneumoniae."}, {"position": 4, "text": "Neumonía por Pneumocystis jirovecii."}]'::jsonb, 4, 4, 'definitiva', NULL, true, 'images/24/image_10.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-011', '712b21a6cb4d4d050c1dfcfa75ce272809693ed4', 2024, 0, 11, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 52 años que consulta por dolor centrotorácico desgarrador de 30 minutos de duración. A la exploración está inquieto y sudoroso. La tensión arterial es de 190/110 mmHg en ambos brazos. A la auscultación no hay soplos cardiacos ni estertores crepitantes. El electrocardiograma está en ritmo sinusal a 90 latidos por minuto sin alteraciones de la repolarización. En la angioTC torácica se observa la imagen que se adjunta. ¿ Cuál es el diagnóstico más probable ?:', '[{"position": 1, "text": "Hematoma intramural."}, {"position": 2, "text": "Úlcera penetrante arteriosclerótica."}, {"position": 3, "text": "Pseudoaneurisma de aorta."}, {"position": 4, "text": "Disección de aorta tipo A de Stanford."}]'::jsonb, 4, 4, 'definitiva', NULL, true, 'images/24/image_11.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-012', 'ff6a7a3d86b95006e20403a43cc7fd0b35374814', 2024, 0, 12, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 75 años sin factores de riesgo cardiovascular. Acude a su centro de salud por disnea de moderados esfuerzos de un año de evolución, que en las últimas semanas aparece ante pequeños esfuerzos. En la exploración física se ausculta en el 2° espacio intercostal derecho un soplo sistólico rudo, irradiado a carótidas con borramiento del 2º tono cardiaco. Se practica un ecocardiograma que muestra una función biventricular normal y un engrosamiento de una de las válvulas cardiacas que presenta un área de 0,95 cm2 (imagen). ¿ Cuál es el diagnóstico más probable y la actitud terapéutica a seguir ?:', '[{"position": 1, "text": "Estenosis valvular aórtica grave con indicación de recambio valvular."}, {"position": 2, "text": "Estenosis valvular aórtica moderada con indicación de seguimiento clínico ambulatorio."}, {"position": 3, "text": "Estenosis mitral grave con indicación de recambio valvular."}, {"position": 4, "text": "Estenosis mitral moderada con indicación de seguimiento clínico ambulatorio."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_12.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-013', '66ccfe85388abb62ddc4356531620815f33484d1', 2024, 0, 13, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'En relación con el electrocardiograma de 12 derivaciones que se muestra, señale la descripción INCORRECTA:', '[{"position": 1, "text": "Ritmo auricular desorganizado con frecuencia ventricular irregular muy sugestiva de fibrilación auricular."}, {"position": 2, "text": "Alteración del sistema de conducción cardiaca con bloqueo bifascicular (bloqueo completo de rama derecha y hemibloqueo anterosuperior izquierdo del haz de His)."}, {"position": 3, "text": "Alteración del sistema de conducción cardiaca con episodios de bloqueo aurículo-ventricular de alto grado o completo."}, {"position": 4, "text": "Elevación significativa del segmento ST en derivaciones inferiores muy sugestiva de\nisquemia miocárdica aguda."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_13.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-014', '8bbc058b20e8c352c582feb771aecb47d03a5acf', 2024, 0, 14, false, false, 'Aparato Digestivo', NULL, 'Paciente de 54 años que acude a realizarse una ecografía abdominal como control de una enfermedad de Crohn. Nunca ha presentado cólicos biliares y no tiene otra comorbilidad relevante. En la imagen se muestran los hallazgos de la ecografía (izquierda modo B y derecha con contraste IV). De las siguientes, señale la afirmación correcta:', '[{"position": 1, "text": "A pesar de que nunca ha tenido síntomas de origen biliar está indicada la colecistectomía como prevención del cáncer de vesícula biliar."}, {"position": 2, "text": "Dado que está asintomático y no tiene riesgo aumentado de cáncer de vesícula biliar no se recomienda la colecistectomía y no es preciso seguimiento por este motivo."}, {"position": 3, "text": "La imagen no es suficientemente concluyente como para tomar una decisión terapéutica. Sería necesario ampliar el estudio con RM y/o PET/TC."}, {"position": 4, "text": "No está indicada la colecistectomía por estar asintomático, pero sí el seguimiento periódico."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_14.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-015', '4309d86a3c7ce9b3b5f3a2455a861353692d7c1d', 2024, 0, 15, false, false, 'Aparato Digestivo', NULL, 'Mujer de 63 años, con antecentes de obesidad, diabetes mellitus, tabaquismo, hipercolesterolemia y enfermedad pulmonar obstructiva crónica. Intervenciones quirúrgicas previas: mastectomía izquierda por cáncer de mama hace 12 años y pancreatectomía distal por tumor neuroendocrino de páncreas hace 2 años. Acude a urgencias por dolor abdominal difuso de reciente aparición, distensión abdominal, vómitos y estreñimiento. Analítica sanguínea con leucocitosis y desviación a la izquierda, sin alteraciones hidroelectrolíticas. Pruebas bioquímicas y de coagulación normales. Tras realización de la TC abdominal que se muestra en la imagen ¿cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Neoplasia de colon."}, {"position": 2, "text": "Eventración abdominal."}, {"position": 3, "text": "Perforación de víscera hueca."}, {"position": 4, "text": "Isquemia mesentérica."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/24/image_15.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-016', 'a0b096e01f981985a7ea36d35b5fad90ad73c8bb', 2024, 0, 16, false, false, 'Hematología', NULL, 'En la mielofibrosis primaria se observan en el frotis sanguíneo (ver imagen) unos hematíes con una forma característica denominados:', '[{"position": 1, "text": "Dacriocitos."}, {"position": 2, "text": "Piropoiquilocitos."}, {"position": 3, "text": "Esquistocitos."}, {"position": 4, "text": "Acantocitos."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_16.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-017', 'ca19d5be9cf6fe3879dda1a892d61f896e41343c', 2024, 0, 17, false, false, 'Nefrología', NULL, 'Hombre de 63 años, fumador de 15 cigarrillos al día como único antecedente de interés, que consulta por cefalea. Se detecta presión arterial de 180/110 mmHg, iniciándose tratamiento con enalapril 10 mg. Se realiza analítica donde no hay ningún parámetro fuera de rango. A la semana se objetiva un buen control de la presión arterial y una creatinina de 3 mg/dL correspondiente a un FGe (filtrado glomerular estimado) de 22 ml/min. En la exploración física se detecta un soplo abdominal. Se realiza una angioTC abdominal (figura). ¿ Cuál de las siguientes afirmaciones es más probable ?:', '[{"position": 1, "text": "Tiene una estenosis unilateral de la arteria renal y la administración de enalapril ha provocado una caída del FGe por la pérdida de vasoconstricción de la arteriola eferente."}, {"position": 2, "text": "Tiene una nefritis intersticial por enalapril."}, {"position": 3, "text": "Tiene una estenosis bilateral de las arterias renales y la administración de enalapril ha provocado una caída del FGe por la pérdida de vasoconstricción de la arteriola eferente."}, {"position": 4, "text": "Tiene una insuficiencia renal aguda debida a la crisis hipertensiva."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_17.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-018', '36fcb692fc6e9615209354fd5bd6746acb473249', 2024, 0, 18, false, false, 'Aparato Digestivo', NULL, 'Mujer de 45 años con proctalgia en relación con la deposición de 12 semanas de evolución. En la exploración en posición genupectoral se observa la siguiente imagen. ¿ Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Fisura anal anterior crónica."}, {"position": 2, "text": "Fisura anal aguda."}, {"position": 3, "text": "Fístula ano-vaginal."}, {"position": 4, "text": "Úlcera anal por enfermedad de Crohn."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_18.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-019', '263eb7ddd858301ee5f45a3c5408619118ac3b98', 2024, 0, 19, false, false, 'Urología', NULL, 'Hombre de 57 años que refiere que hace 7 días comenzó de forma súbita con dolor en flanco izquierdo con irradiación anterior, náuseas y vómitos, que ha acudido cuatro veces a urgencias por este motivo. Hoy acude nuevamente, ya que el dolor no se controla con la analgesia pautada. Se objetiva tensión arterial media de 63 mmHg, temperatura 38,5 ℃ y obnubilación. En la analítica sanguínea destacan 3.300 leucocitos/mm3 con 80 % segmentados, creatinina 1,4 mg/dl y proteína C reactiva 7,5 mg/dl (<0,5 mg/dl). Sedimento urinario con pH 5, nitritos, leucocituria, microhematuria y bacteriuria. Se solicitan radiografía simple de abdomen y ecografía abdominal (imágenes). Ante estos hallazgos ¿cuál de las siguientes es la actitud más adecuada ?:', '[{"position": 1, "text": "Antibioticoterapia, sueroterapia, analgesia y alcalinización intravenosas y un alfa-bloqueante vía oral y observación en urgencias hasta control sintomático."}, {"position": 2, "text": "Antibioticoterapia y sueroterapia intravenosas y derivación urgente de la vía urinaria mediante catéter doble jota o nefrostomía percutánea, con tratamiento diferido del agente causal."}, {"position": 3, "text": "Antibioticoterapia, sueroterapia, analgesia intravenosas y un alfa-bloqueante vía oral e ingreso en la Unidad de Cuidados Intensivos."}, {"position": 4, "text": "Antibioticoterapia y sueroterapia intravenosas y litotricia extracorpórea por ondas de choque o ureterorrenoscopia."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/24/image_19.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-020', '4d43cef82807821ab941c26c158fa464750fc4ee', 2024, 0, 20, false, false, 'Neurología y Neurocirugía', NULL, 'Ante esta imagen en un paciente con un trastorno motor en miembros inferiores, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Debemos buscar una malformación de Chiari."}, {"position": 2, "text": "En algunos casos se asocia a hidrocefalia."}, {"position": 3, "text": "Se caracteriza por una pérdida de la sensibilidad táctil y vibratoria con preservación de la sensación térmica y dolorosa."}, {"position": 4, "text": "Puede producirse tras traumatismos o infecciones."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_20.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-021', '8a3dec65177c08110ec97018daba9d396219af04', 2024, 0, 21, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Un paciente de 27 años, tras sufrir una caída de un caballo, presenta un traumatismo en el miembro inferior izquierdo con una actitud del mismo en flexión, aducción y rotación interna. Tras realizarle la radiografía anteroposterior de pelvis que se muestra, señale cuál es el diagnóstico:', '[{"position": 1, "text": "Fractura pertrocantérea de fémur izquierdo."}, {"position": 2, "text": "Fractura subcapital de fémur izquierdo."}, {"position": 3, "text": "Luxación anterior de cadera, con fractura de pared anterior de acetábulo."}, {"position": 4, "text": "Luxación posterior de cadera, con fractura de pared posterior de acetábulo."}]'::jsonb, 4, 4, 'definitiva', NULL, true, 'images/24/image_21.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-022', 'd24eb6edba6d0f60e02f19f09f2675f889ba33d6', 2024, 0, 22, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Mujer de 75 años, autónoma y activa, que sufre una caída en su domicilio y acude a urgencias con dolor, impotencia funcional y deformidad alrededor de la rodilla izquierda. Había sido intervenida quirúrgicamente de esta rodilla hacía 2 años por gonartrosis mediante una artroplastia total de rodilla cementada postero-estabilizada. Los pulsos distales están conservados. Existe una movilidad patológica de la rodilla izquierda sin apreciarse déficit neurológico en la pierna afecta. Se realizan la radiografía y la TC que se muestran en las imágenes. ¿ Cuál de las siguientes sería la actitud terapéutica en esta situación ?:', '[{"position": 1, "text": "Placa condílea de ángulo fijo a 95 grados con tornillos de compresión interfragmentaria."}, {"position": 2, "text": "Placa condílea de fémur bloqueada de fijación angular."}, {"position": 3, "text": "Clavo de fémur retrógrado acerrojado largo."}, {"position": 4, "text": "Clavo anterógrado cérvico-cefálico de fémur para proteger todo el fémur."}]'::jsonb, 4, 2, 'definitiva', NULL, true, 'images/24/image_22.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-023', '7d3be279fc68f87028ca0523ac99ce1d2e5b8ddc', 2024, 0, 23, false, false, 'Oftalmología', NULL, 'Mujer de 84 años que consulta a su médico de familia por la lesión en el párpado inferior de 2 meses de evolución que aparece en la imagen. ¿Cuál de los siguientes diagnósticos es el más probable ?:', '[{"position": 1, "text": "Carcinoma basocelular ulcerado."}, {"position": 2, "text": "Blefaritis."}, {"position": 3, "text": "Orzuelo externo."}, {"position": 4, "text": "Dermatitis eccematosa."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_23.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-024', '387073c90f5102b1694b23179e13efc9fabdd528', 2024, 0, 24, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Paciente que consulta porque se ha notado "bultos" cervicales bilaterales y molestias faríngeas de meses de evolución, incluso con leve dificultad para tragar. No refiere disnea ni disfonía, pero observamos una voz engolada. Ha perdido 3 Kg de peso recientemente. No es fumador pero sí ha sido bebedor importante. Después de explorar la cavidad oral y orofaringe sin hallar alteraciones, se realiza la videofibroscopia de vía aerodigestiva superior, una de cuyas imágenes se muestra. ¿ Cuál de las siguientes descripciones es correcta ?:', '[{"position": 1, "text": "Lesión que respeta las cuerdas vocales sugestiva de carcinoma de supraglotis."}, {"position": 2, "text": "Lesión transglótica sugestiva de carcinoma de laringe T2."}, {"position": 3, "text": "Lesión en seno piriforme sugestiva de carcinoma de hipofaringe."}, {"position": 4, "text": "Lesión en amígdala palatina derecha sugestiva de carcinoma de orofaringe T2."}]'::jsonb, 4, 1, 'definitiva', NULL, true, 'images/24/image_24.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-025', '036ee52ce4e5a69461412214c6fd78cf09d01bd7', 2024, 0, 25, false, false, 'Neumología y Cirugía Torácica', NULL, 'Mujer de 57 años sin antecedentes de interés que consulta por presentar desde hace 2 meses sensación disneica, que en la última semana se ha hecho de mínimos esfuerzos. No presenta fenómeno de Raynaud, fiebre ni ortopnea. A la exploración física destacan las lesiones cutáneas que se observan en la imagen. No presenta edemas, la auscultación cardíaca es normal y la auscultación respiratoria muestra crepitantes secos en ambas bases pulmonares. La radiografía de tórax muestra un índice cardiotorácico normal y un discreto patrón intersticial basal derecho. En la analítica destaca únicamente una VSG de 75 mm, hemograma normal, AST, ALT, CK, creatinina y ionograma con valores normales. ¿ Cuál de las siguientes actitudes diagnósticas es la más apropiada ?:', '[{"position": 1, "text": "Determinar la presencia de anticuerpos anti-PL7, anti-PL12 y anti-Jo1."}, {"position": 2, "text": "Determinar la presencia de anticuerpos anti- centrómero."}, {"position": 3, "text": "Determinar la presencia de anticuerpos anti- MDA5."}, {"position": 4, "text": "Solicitar una TC torácica de alta resolución."}]'::jsonb, 4, 3, 'definitiva', NULL, true, 'images/24/image_25.png', false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-026', '6cd5bc43480f2f7458a6b211788045bbb53ba943', 2024, 0, 26, false, false, 'Neumología y Cirugía Torácica', NULL, 'Una persona joven y sana se encuentra en posición anatómica erguida. En relación con el flujo sanguíneo a través de los pulmones y su distribución, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "En situación de reposo, el flujo en los vértices pulmonares es habitualmente intermitente."}, {"position": 2, "text": "El ejercicio aumenta el flujo sanguíneo en todas las regiones pulmonares."}, {"position": 3, "text": "El aumento del gasto cardiaco durante el ejercicio intenso es asumido por la circulación pulmonar sin grandes aumentos en la presión arterial pulmonar."}, {"position": 4, "text": "Una disminución significativa de la concentración de O2 en los alveolos provoca una vasodilatación de los vasos adyacentes."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-027', '7117e8de962ac08f59737198cb748170dbcf31b7', 2024, 0, 27, false, false, 'Endocrinología', NULL, '¿ Cuál de las siguientes alteraciones bioquímicas se observa en el reordenamiento metabólico de la diabetes mellitus?:', '[{"position": 1, "text": "La disminución de la traslocación de los transportadores de glucosa GLUT2 y GLUT4 desde las vesículas de almacenamiento intracelular a la membrana plasmática."}, {"position": 2, "text": "El aumento de la producción de urea por una mayor degradación nucleotídica."}, {"position": 3, "text": "El incremento de la síntesis hepática de triglicéridos."}, {"position": 4, "text": "El aumento de la síntesis hepática de glicerol como sustrato gluconeogénico."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-028', '213d3d94c6957c83556361f395c31da028ab3734', 2024, 0, 28, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'En relación con el potencial de acción cardiaco, señale la afirmación correcta:', '[{"position": 1, "text": "Las células automáticas tienen un potencial de acción lento y calciodependiente."}, {"position": 2, "text": "El potencial de reposo de las células automáticas es más negativo que el de las células del miocardio ventricular."}, {"position": 3, "text": "Las células automáticas tienen canales rápidos de sodio."}, {"position": 4, "text": "Los canales If se sitúan predominantemente en las células del miocardio ventricular."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-029', '9212e0944a5e6505ee6bf2b5b23b16044426a83d', 2024, 0, 29, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, '¿ Cuál de las siguientes características de la anatomía del esófago es la que facilita la realización de la ecocardiografía transesofágica ?:', '[{"position": 1, "text": "El cayado aórtico contacta con el esófago a la altura de la 4ª vértebra dorsal y lo proyecta hacia delante."}, {"position": 2, "text": "El segmento torácico del esófago discurre por la cara posterior de aurícula y ventrículo derechos."}, {"position": 3, "text": "El esófago recorre la cara posterior de la aurícula izquierda."}, {"position": 4, "text": "La existencia de un segmento del esófago más dilatado entre la estrechez aórtica y la estrechez diafragmática."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-030', 'a4742e4e4b142722a0a68144f1db23c0f42416dc', 2024, 0, 30, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'De las siguientes afirmaciones relacionadas con las estructuras anatómicas que forman el manguito de los rotadores, señale la correcta:', '[{"position": 1, "text": "Los músculos que forman el manguito de los rotadores son el subescapular, el supraespinoso, el infraespinoso y el redondo mayor."}, {"position": 2, "text": "Los tendones de los músculos del manguito refuerzan la cápsula fibrosa de la articulación escápulo-humeral."}, {"position": 3, "text": "El músculo infraespinoso rota el brazo en dirección interna."}, {"position": 4, "text": "El músculo supraespinoso ayuda a la aducción (aproximación) del brazo."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-031', 'a42fdfa1cf6c4902e653f46ddd502940da34a7b4', 2024, 0, 31, false, false, 'Hematología', NULL, 'En relación con el metabolismo del hierro y su control mediado por hepcidina, es cierto que:', '[{"position": 1, "text": "La caída en la presión parcial de oxígeno promueve la activación del factor inducible por hipoxia (HIF), que aumenta la expresión de hepcidina."}, {"position": 2, "text": "El aumento de hierro sérico o la inflamación estimulan la síntesis de hepcidina en el hígado, que regula negativamente la función de la ferroportina."}, {"position": 3, "text": "La hepcidina disminuye la absorción intestinal de hierro a través de la inactivación del transportador de metales bivalentes 1 (DMT1)."}, {"position": 4, "text": "En la hemocromatosis hereditaria de tipo 1, las mutaciones en la proteína de la hemocromatosis humana (HFE) causan un aumento de la producción de hepcidina."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-032', '3d78c3cbd04a2121c2fd2412f442d1eb7fccef7d', 2024, 0, 32, false, false, 'Nefrología', NULL, 'Una persona sana sufre una deshidratación tras realizar ejercicio físico intenso a altas temperaturas sin ingerir líquidos. Respecto a la activación del sistema renina-angiotensina- aldosterona en esas condiciones, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Los cambios de presión arterial se acompañan de cambios proporcionales en la filtración glomerular."}, {"position": 2, "text": "Se produce vasoconstricción de las arteriolas eferentes."}, {"position": 3, "text": "Aumenta la actividad de los núcleos hipotalámicos supraóptico y paraventricular."}, {"position": 4, "text": "Aumenta la secreción renal de potasio."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-033', 'd537daa6d8af45f550dd44355e2f88f430cc6713', 2024, 0, 33, false, false, 'Aparato Digestivo', NULL, 'Un paciente acude a consulta recientemente diagnosticado de esofagitis eosinofílica y tras exponerle las opciones de tratamiento prefiere hacer tratamiento dietético con dieta de exclusión de dos alimentos. ¿ Cuáles son los alimentos que tendría que retirar de la dieta ?:', '[{"position": 1, "text": "Huevo y trigo."}, {"position": 2, "text": "Leche de vaca y pescado."}, {"position": 3, "text": "Legumbres y leche de vaca."}, {"position": 4, "text": "Leche de vaca y trigo."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-034', 'c5a3cdb90b5a6692479de2e7414337f55ccc6578', 2024, 0, 34, false, false, 'Genética e Inmunología', NULL, 'En relación con el mecanismo inmunológico implicado el rechazo de órganos sólidos trasplantados, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El rechazo agudo mediado por linfocitos T puede ser controlado mediante el uso de fármacos como la ciclosporina A o los corticoides."}, {"position": 2, "text": "La presencia en el receptor de anticuerpos específicos contra el donante (DSA) previa al trasplante es una contraindicación para el mismo."}, {"position": 3, "text": "El rechazo crónico o lesión crónica del injerto se asocia al daño del endotelio mediado por anticuerpos anti-HLA."}, {"position": 4, "text": "El rechazo hiperagudo es mediado por linfocitos T citotóxicos contra antígenos del donante presentes en el receptor."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-035', '12315ce2715c50fdeb41a37b78ea0645f96e12d8', 2024, 0, 35, false, false, 'Dermatología', NULL, 'En un paciente de 16 años de edad que presenta desde hace varios meses, importante sequedad de la piel lesiones eccematosas en zonas de flexión, fundamentalmente en las fosas cubital y poplítea, de carácter muy pruriginoso que inducen al rascado, y que cursa con exacerbaciones y remisiones, el diagnóstico clínico más probable es:', '[{"position": 1, "text": "Dermatitis alérgica de contacto."}, {"position": 2, "text": "Dermatitis atópica."}, {"position": 3, "text": "Dermatitis seborreica."}, {"position": 4, "text": "Dermatitis dishidrótica."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-036', '046e65c26035dd6893af6639d856c4b001690076', 2024, 0, 36, false, false, 'Genética e Inmunología', NULL, 'Las células tumorales desarrollan diferentes mecanismos dirigidos a evitar la activación de la respuesta inmunitaria antitumoral. Entre las inmunoterapias antitumorales dirigidas a contrarrestar estos mecanismos de evasión destaca:', '[{"position": 1, "text": "La inoculación intratumoral de células T reguladoras específicas frente a antígenos tumorales."}, {"position": 2, "text": "La inoculación de células de la inmunidad innata con capacidad antitumoral como las células reguladoras de origen mieloide (myeloid-derived suppressor cells, MDSC)."}, {"position": 3, "text": "El uso de citocinas como el TGF-beta o la IL-10 que frenan el crecimiento tumoral."}, {"position": 4, "text": "El uso de anticuerpos monoclonales inmunomoduladores frente a PD-1 o los ligandos de PD-1."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-037', 'f6e88b41695f9502687621aab3f5d5a5270a9bbb', 2024, 0, 37, false, false, 'Neurología y Neurocirugía', NULL, 'Una de las siguientes enfermedades se produce por hipermetilación de una expansión de tripletes CGG en la región promotora:', '[{"position": 1, "text": "Enfermedad de Hungtinton."}, {"position": 2, "text": "Ataxia de Friedreich."}, {"position": 3, "text": "Síndrome del cromosoma X frágil."}, {"position": 4, "text": "Distrofia miotónica tipo 1."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-038', '2aa3cc4d226a4d73a097b6236e45eefe52142f3d', 2024, 0, 38, false, false, 'Neumología y Cirugía Torácica', NULL, 'En el asma bronquial son numerosas las células que participan en la inflamación de la vía aérea. En relación con las diferentes poblaciones linfocitarias y las citocinas que liberan ¿cuál de las siguientes afirmaciones es correcta ?:', '[{"position": 1, "text": "Los linfocitos B son los responsables de la coordinación de la respuesta inflamatoria."}, {"position": 2, "text": "En el asma bronquial hay un predominio de fenotipo linfocitario TH1."}, {"position": 3, "text": "Las citocinas IL4 e IL13 son las favorecedoras de la síntesis de IgE."}, {"position": 4, "text": "La población de linfocitos T reguladores (CD4+ y CD25+) está aumentada."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-039', '5536bd639f0bf09a717876eb07bc9aac49f88674', 2024, 0, 39, false, false, 'Genética e Inmunología', NULL, 'En relación con las enfermedades asociadas al mecanismo de hipersensibilidad tipo II, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "La presencia de anticuerpos frente al receptor de las hormonas tiroideas T3 y T4 se asocia a la enfermedad de Graves."}, {"position": 2, "text": "La presencia de autoanticuerpos anti- desmogleína se asocia al pénfigo vulgar."}, {"position": 3, "text": "La miastenia gravis se asocia a la presencia de anticuerpos frente al receptor de la acetilcolina."}, {"position": 4, "text": "El síndrome de Goodpasture se asocia a la presencia de anticuerpos frente a la membrana basal glomerular renal y pulmonar."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-040', '85e85f4b1002f8d91efd911e35ffba193d922edf', 2024, 0, 40, false, false, 'Endocrinología', NULL, 'Un rasgo que aparece en todas las generaciones, tanto en varones como en mujeres, pero los varones no lo transmiten a sus hijos varones, se corresponde con uno de los siguientes patrones de herencia:', '[{"position": 1, "text": "Autosómica dominante."}, {"position": 2, "text": "Ligada al sexo dominante."}, {"position": 3, "text": "Ligada al sexo recesiva."}, {"position": 4, "text": "Mitocondrial."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-041', 'd860f80aaa5ca134b7ba13cfae6784ce93380d79', 2024, 0, 41, false, false, 'Dermatología', NULL, 'Mujer de 63 años en tratamiento con sulfamidas (trimetoprim-sulfametoxazol) vía oral por una infección de vías urinarias bajas. Acude a urgencias por presentar lesiones cutáneas y en mucosas (oral, conjuntival y genital). Las lesiones cutáneas tienen forma de máculas irregulares oscuras, con desprendimiento cutáneo y afectan a más del 30 % de la superficie corporal. Se interpreta como una posible reacción farmacológica grave. ¿ Cuál de los siguientes diagnósticos es más probable ?:', '[{"position": 1, "text": "Eritema multiforme."}, {"position": 2, "text": "Síndrome de Stevens-Johnson."}, {"position": 3, "text": "Necrólisis epidérmica tóxica."}, {"position": 4, "text": "Síndrome de hipersensibilidad inducido por fármacos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-042', 'a3b10d3b03b590738ab5a807d42e1dfd10747eba', 2024, 0, 42, false, false, 'Genética e Inmunología', NULL, 'La vacunación utilizando ARN mensajero de la proteína S (Spike) del SARS-COV-2 va dirigida a la protección de la población frente a la COVID-19. En relación con la respuesta a esta vacuna señale la afirmación INCORRECTA:', '[{"position": 1, "text": "La respuesta no requiere la colaboración de los linfocitos T, al ser un antígeno timo- independiente."}, {"position": 2, "text": "Un porcentaje\nelevado de pacientes inmunodeprimidos, como aquellos con trasplante de órganos o con inmunodeficiencia, tienen un defecto en la respuesta a esta vacuna."}, {"position": 3, "text": "Es una forma de inmunización activa cuyo resultado se asocia al cambio de isotipo de los anticuerpos."}, {"position": 4, "text": "Induce memoria inmunológica basada en la activación de linfocitos B."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-043', '59ebc56753a06212a0272edf2181263a5dcc4446', 2024, 0, 43, false, false, 'Bioestadística', NULL, 'Para establecer si la exposición a radiaciones ionizantes de los trabajadores de una mina influye en la aparición de muertes por cáncer de pulmón se decide en el año 2010 realizar un estudio. Los investigadores recopilan información del registro de exposición a radiaciones en la empresa minera, con datos sobre las radiaciones acumuladas por cada trabajador desde el año 1980 al 2000, año en que se cierra la mina. Y también recogen información sobre las muertes por cáncer de pulmón en esos trabajadores desde el año 1980 al año 2008, a partir de los registros de mortalidad existentes. Finalmente, comparan la mortalidad por cáncer de pulmón entre los trabajadores con mayor y menor exposición a las radiaciones ionizantes. ¿ Qué tipo de diseño epidemiológico es éste ?:', '[{"position": 1, "text": "Estudio de casos y controles retrospectivo."}, {"position": 2, "text": "Estudio de casos y controles prospectivo."}, {"position": 3, "text": "Estudio de cohortes retrospectivo."}, {"position": 4, "text": "Estudio de cohortes prospectivo."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-044', '6f9a49af0a3172abff1bf94cb209f0aad1e74499', 2024, 0, 44, false, false, 'Bioestadística', NULL, 'Al aumentar el tamaño muestral de un estudio transversal (o de prevalencia) aumenta:', '[{"position": 1, "text": "La representatividad de la muestra."}, {"position": 2, "text": "La validez del estudio."}, {"position": 3, "text": "La reproducibilidad del estudio."}, {"position": 4, "text": "La precisión del estudio."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-045', '0c9d58de4e6ce394c6d055849875986a90c97da7', 2024, 0, 45, false, false, 'Bioestadística', NULL, '¿Qué tipo de estudio epidemiológico NO PERMITE calcular un riesgo relativo?:', '[{"position": 1, "text": "Un ensayo clínico aleatorizado."}, {"position": 2, "text": "Un estudio de cohortes retrospectivo."}, {"position": 3, "text": "Un estudio de cohortes prospectivo."}, {"position": 4, "text": "Un estudio de casos y controles."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-046', 'c15c50e75aa493cb19381e69c2611a8afc8d9630', 2024, 0, 46, false, false, 'Bioestadística', NULL, 'En un estudio sobre la validez de una prueba diagnóstica, para resumir la relación entre la sensibilidad y la especificidad de la prueba se puede usar:', '[{"position": 1, "text": "El índice de Kappa."}, {"position": 2, "text": "La curva ROC (receiver operating characteristics)."}, {"position": 3, "text": "El coeficiente de correlación intraclase."}, {"position": 4, "text": "El gráfico de Altman y Bland."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-047', '0bd6a0e47d49125dfb0d1bacf21651203b2a7496', 2024, 0, 47, false, false, 'Bioestadística', NULL, 'En relación con las condiciones necesarias para la implementación de un programa de cribado poblacional de cáncer, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Debe existir una prueba adecuada para la detección, independientemente de la aceptabilidad de la prueba en la población."}, {"position": 2, "text": "La enfermedad que se detecta mediante el cribado debe ser relevante desde el punto de vista de salud pública."}, {"position": 3, "text": "La enfermedad que se detecta mediante el cribado debe ser tratable en la etapa presintomática y el daño potencial de la intervención debe ser inferior al del tratamiento en la etapa sintomática."}, {"position": 4, "text": "Se debe disponer de recursos suficientes para la implementación de la estrategia a medio / largo plazo."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-048', 'eb647a35587d17d36bf4018276bd9c42fcb2033b', 2024, 0, 48, false, false, 'Miscelánea', NULL, 'Uno de los siguientes fármacos, además de su efecto analgésico, posee un efecto relajante de fibra muscular lisa:', '[{"position": 1, "text": "Diclofenaco."}, {"position": 2, "text": "Paracetamol."}, {"position": 3, "text": "Ketorolaco."}, {"position": 4, "text": "Metamizol."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-049', 'd19b34706b65678493da3df055a699e84447627d', 2024, 0, 49, false, false, 'Bioestadística', NULL, 'Para la detección de reacciones adversas a medicamentos poco frecuentes (<1/10.000) el método de fármacovigilancia más adecuado es:', '[{"position": 1, "text": "Notificaciones espontáneas."}, {"position": 2, "text": "Monitorización intensiva hospitalaria."}, {"position": 3, "text": "Estudios de cohorte."}, {"position": 4, "text": "Metaanálisis."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-050', 'f1b268d02f327069401f81c627d9c7fd6364d10a', 2024, 0, 50, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Según la clasificación del estado físico preoperatorio del paciente establecida por la ASA (Sociedad Americana de Anestesiología), un paciente con hipertensión arterial mal controlada correspondería a un grado:', '[{"position": 1, "text": "IV"}, {"position": 2, "text": "III"}, {"position": 3, "text": "II"}, {"position": 4, "text": "I"}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2024-v0-051', 'a517e1c31e2432d768f8b1e5e9c80cfe093abcc3', 2024, 0, 51, false, false, 'Bioestadística', NULL, 'Un artículo describe un ensayo clínico aleatorizado en fase IV en una muestra de adultos obtenida de 42 centros sanitarios de 16 países distintos que recibieron un fármaco en estudio y un placebo durante 12 semanas. ¿ Cuál de las siguientes afirmaciones describe mejor el contexto de esta investigacion atendiendo a estas características ?:', '[{"position": 1, "text": "Al ser una investigación aleatorizada, el número de hombres en cada uno de los grupos experimentales (fármaco o placebo) debe ser el mismo que el de mujeres."}, {"position": 2, "text": "El fármaco que se investiga en este ensayo ya se encuentra aprobado para su prescripción en otras indicaciones o situaciones clínicas."}, {"position": 3, "text": "Este ensayo clínico trata de analizar en personas sanas y enfermas las dosis terapéuticas de un fármaco experimental en comparación con un placebo."}, {"position": 4, "text": "Este tipo de ensayo se denomina metaanálisis al incluir pacientes de distintos centros sanitarios y países."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-052', '78ec9d1ee8238a6ec09acef8835c15fa0ff7180d', 2024, 0, 52, false, false, 'Psiquiatría', NULL, 'Un hombre de 52 años se está recuperando de una dependencia al alcohol y solicita apoyo farmacológico para prevenir la recaída y mantenerse abstinente. ¿ Cuál de los siguientes medicamentos está indicado como tratamiento complementario para mantener la abstinencia en el marco de un programa de tratamiento de pacientes desintoxicados que han sido dependientes de alcohol ?:', '[{"position": 1, "text": "Vareniclina."}, {"position": 2, "text": "Nalmefeno."}, {"position": 3, "text": "Acamprosato."}, {"position": 4, "text": "Tiamina."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-053', 'fb818ad407f62ef9352ef01681442b30d66ed9de', 2024, 0, 53, false, false, 'Miscelánea', NULL, 'La hipertermia maligna NO se relaciona con:', '[{"position": 1, "text": "Succinilcolina."}, {"position": 2, "text": "Desflurano."}, {"position": 3, "text": "Propofol."}, {"position": 4, "text": "Sevoflurano."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-054', '2bd0a15db513fe69973123e2eb5ba49aa9f7830d', 2024, 0, 54, false, false, 'Bioestadística', NULL, 'Un ensayo clínico cuyo objetivo fundamental es obtener datos preliminares de eficacia terapéutica y establecer la relación entre las dosis y la eficacia para determinar un intervalo de dosis adecuadas, es un:', '[{"position": 1, "text": "Estudio preclínico."}, {"position": 2, "text": "Ensayo clínico fase I."}, {"position": 3, "text": "Ensayo clínico fase II."}, {"position": 4, "text": "Ensayo clínico fase III."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-055', 'e1c399d5342de66d5d8069d8714bdfe9fa36812e', 2024, 0, 55, false, false, 'Oftalmología', NULL, 'Mujer de 57 años que consulta para una revisión rutinaria. En la exploración oftalmológica presenta una agudeza visual (AV) sin corrección de 1,0 en OD y 0,5 en OI, la AV con agujero estenopeico es de 1,0 en ambos ojos y la presión intraocular es de 16 mmHg en ambos ojos. ¿ Cuál de las siguientes sería la actitud a seguir más correcta ?:', '[{"position": 1, "text": "Realizar un estudio refractivo para valorar un defecto de refracción."}, {"position": 2, "text": "Realizar un campo visual para descartar un déficit visual periférico en OI."}, {"position": 3, "text": "Realizar un estudio de fondo de ojo para valorar una patología macular en el OI."}, {"position": 4, "text": "Hacer un seguimiento en un año para valorar la evolución de la AV."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-056', 'bddb872b39583bb1995da5172172288f01450636', 2024, 0, 56, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'El carcinoma adenoide quístico:', '[{"position": 1, "text": "Es el tumor maligno más frecuente de las glándulas salivares."}, {"position": 2, "text": "Nunca afecta las glándulas salivares menores a nivel del paladar."}, {"position": 3, "text": "Puede asociarse con parálisis facial debido a su neurotropismo."}, {"position": 4, "text": "Se debe tratar con radioterapia como primera opción terapéutica."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-057', 'd8f1b7259b306763bd9f5a36852902e9b07e3d8e', 2024, 0, 57, false, false, 'Neurología y Neurocirugía', NULL, 'Hombre de 40 años que presenta un cuadro vertiginoso de varias horas de evolución. No presenta hipoacusia, acúfenos ni sensación de taponamiento ótico. En la exploración se observa un nistagmo espontáneo. ¿ Qué características del nistagmo orientarán hacia un vértigo periférico ?:', '[{"position": 1, "text": "Nistagmo horizontal, unidireccional, que aumenta de intensidad cuando se dirige al lado de la fase rápida."}, {"position": 2, "text": "Nistagmo vertical, unidireccional, que no se suprime con la fijación de la mirada."}, {"position": 3, "text": "Nistagmo horizontal, con componente rotatorio, que cambia de dirección cuando se dirige al lado de la fase lenta."}, {"position": 4, "text": "Nistamo horizontal, con componente rotatorio que no se suprime con la fijación de la mirada."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-058', '9d906270bd7aceb338f600ba056272aff6f3a157', 2024, 0, 58, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Hombre de 48 años, profesor universitario, que refiere sufrir problemas con la voz desde hace varios años, que han empeorado progresivamente y que consisten en voz áspera y forzada, con posibles cambios de tono, cansancio y fatiga al hablar. En la exploración fibrovideoendoscópica faringolaríngea no se observan lesiones orgánicas en las cuerdas vocales, pero sí una disminución del diámetro anteroposterior del vestíbulo laríngeo durante la fonación. El diagnóstico más probable del trastorno vocal que padece este paciente es:', '[{"position": 1, "text": "Parálisis abductora laríngea."}, {"position": 2, "text": "Disfonía espasmódica."}, {"position": 3, "text": "Distonía de la musculatura extrínseca laríngea."}, {"position": 4, "text": "Disfonía por tensión muscular."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-059', '351d6f7a81d99498a16555db47542782c5bc1380', 2024, 0, 59, false, false, 'Traumatología y Cirugía Ortopédica', NULL, '¿Cuál de los siguientes colgajos NO PODRÍA ser utilizado para realizar la reconstrucción de un defecto en la región cervical posterior ?:', '[{"position": 1, "text": "Colgajo anterolateral fasciocutáneo de muslo, pediculado."}, {"position": 2, "text": "Colgajo libre de músculo dorsal ancho con isla cutánea."}, {"position": 3, "text": "Colgajo pediculado de trapecio (musculocutáneo)."}, {"position": 4, "text": "Colgajo libre SCIP (derivado del sistema circunflejo ilíaco superficial)."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-060', '7e827b7936e491e810d7b79465eee01529906a1b', 2024, 0, 60, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Respecto al cáncer de lengua:', '[{"position": 1, "text": "El tipo histológico más frecuente es el carcinoma basocelular y su tratamiento primario es habitualmente radioterápico."}, {"position": 2, "text": "Se relaciona con factores etiopatogénicos como la irradiación solar y el virus del papiloma humano."}, {"position": 3, "text": "Rara vez provoca metástasis por vía linfática."}, {"position": 4, "text": "El tipo histológico más frecuente es el carcinoma epidermoide y su tratamiento quirúrgico asocia habitualmente disección ganglionar cervical."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-061', '1c3b0b2436988c225dc44aea8dc3e9ba40b15642', 2024, 0, 61, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Las siguientes enfermedades sistémicas pueden cursar con síntomas otorrinolaringológicos. Señale aquella que puede afectar con mayor frecuencia (aproximadamente 70-80 % de los casos) a la cavidad nasal, la cavidad bucal y la orofaringe, y que en la mitad de los casos puede existir también afectación laríngea:', '[{"position": 1, "text": "Penfigoide."}, {"position": 2, "text": "Policondritis recidivante."}, {"position": 3, "text": "Sarcoidosis."}, {"position": 4, "text": "Pénfigo."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-062', '4d5feec103599c152a44bae2505b6ea998a02cb2', 2024, 0, 62, false, false, 'Oftalmología', NULL, 'Hombre de 45 años con antecedentes de queratitis herpética de repetición en ojo izquierdo (OI). Consulta por dolor, hiperemia y visión borrosa en OI de un día de evolución. A la exploración presenta una agudeza visual con su corrección de 1,0 en OD y 0,6 en OI, la presión intraocular es de 18 mmHg en OD y 35 mmHg en OI. La exploración con lámpara de hendidura en OD es normal y en el OI presenta hiperemia ciliar, turbidez en cámara anterior, ligero leucoma corneal y un test de fluoresceína negativo. ¿ Con cuál de las siguientes patologías relacionaría este cuadro clínico ?:', '[{"position": 1, "text": "Uveítis hipertensiva."}, {"position": 2, "text": "Glaucoma maligno."}, {"position": 3, "text": "Glaucoma neovascular."}, {"position": 4, "text": "Queratitis epitelial herpética."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-063', 'de4f02e0ac8b43866cd1ce9f7bda69178f0cb24c', 2024, 0, 63, false, false, 'Neurología y Neurocirugía', NULL, 'El defecto campimétrico asociado a una lesión en la cintilla óptica derecha es:', '[{"position": 1, "text": "Hemianopsia homónima izquierda."}, {"position": 2, "text": "Hemianopsia heterónima bitemporal."}, {"position": 3, "text": "Cuadrantanopsia homónima izquierda."}, {"position": 4, "text": "Cuadrantanopsia homónima derecha."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-064', '80a094b320546fd29362d6e842d8d66de13c19e3', 2024, 0, 64, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer de 17 años que consulta porque no tiene la menstruación desde hace 7 meses. No refiere antecedentes de interés ni otra sintomatología. No ha acudido antes porque estaba entrenando en un centro deportivo de alto rendimiento. Tuvo la menarquia a los 13 años, ciclos muy irregulares, sin dismenorrea y una interrupción legal del embarazo a los 16 años. La analítica muestra hemograma normal, FSH <0,1 U/L, LH <0,1 U/L, estradiol <5,0 pg/mL, TSH 1,56 mU/L. ¿ Cuál de los siguientes es el diagnóstico más probable y la actitud a seguir ?:', '[{"position": 1, "text": "Fallo ovárico prematuro, por lo que le pauta terapia hormonal sustitutiva y control en 3 meses."}, {"position": 2, "text": "Síndrome de Asherman, por lo que indica una histeroscopia."}, {"position": 3, "text": "Amenorrea central hipofisaria (síndrome de Sheehan), por lo que solicita resonancia magnética cerebral para confirmar el diagnóstico y pautar tratamiento sustitutivo."}, {"position": 4, "text": "Amenorrea central hipotalámica funcional, por lo que solicita resonancia magnética para descartar otras patologías."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-065', '64e77106aeeb587e5febebf669f3ed5ed762164a', 2024, 0, 65, false, false, 'Ginecología y Obstetricia', NULL, 'Gestante de 16 semanas con antecedente de parto prematuro a las 33 semanas en una gestación anterior, que actualmente presenta una longitud cervical de 28 mm. ¿ Cúal es la intervención más eficaz para la prevención de la recurrencia del parto prematuro ?:', '[{"position": 1, "text": "Reposo relativo, antibioticoterapia y nifedipino via oral."}, {"position": 2, "text": "Progesterona natural micronizada vía vaginal."}, {"position": 3, "text": "Cerclaje profiláctico."}, {"position": 4, "text": "Pesario cervical."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-066', 'd7a1017e7ecc23f05ca7f246bf61d179ea5593c4', 2024, 0, 66, false, false, 'Ginecología y Obstetricia', NULL, '¿ En cuál de las siguientes pacientes NO estaría indicada la realización de una histeroscopia diagnóstica como primera línea de estudio ?:', '[{"position": 1, "text": "Mujer de 32 años con estudio ecográfico normal, episodios de dismenorrea grave y esterilidad primaria."}, {"position": 2, "text": "Mujer de 70\naños con metrorragia postmenopáusica de 1 mes de evolución."}, {"position": 3, "text": "Mujer de 45 años con hemorragia uterina anormal cíclica de 6 meses de evolución."}, {"position": 4, "text": "Mujer de 43 años con hemorragia uterina anormal acíclica y sospecha ecográfica de mioma tipo 2 de la FIGO."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-067', 'dd10b274f723c7f908a30ded036e909130023dc4', 2024, 0, 67, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer de 29 años sin antecedentes de interés que acude por deseo gestacional de más de dos años. Refiere reglas regulares de 4 días de duración con dismenorrea que le impide su actividad habitual, dolor a la defecación y dispareunia. ¿ Cúal de las siguientes es la sospecha diagnóstica ?:', '[{"position": 1, "text": "Endometriosis."}, {"position": 2, "text": "Insuficiencia ovárica prematura."}, {"position": 3, "text": "Síndrome del ovario poliquístico."}, {"position": 4, "text": "Esterilidad de origen tubárico."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-068', '82c30618fc3553925e9471c942af1f3697eddd2f', 2024, 0, 68, false, false, 'Ginecología y Obstetricia', NULL, 'Gestante de 37 semanas, fumadora, que acude a urgencias por sangrado vaginal similar a la regla, sin otros síntomas. No tiene antecedentes de interés salvo una cesárea. No se ha controlado la gestación. A la exploración se objetiva un sangrado constante, activo y brillante. El registro cardiotocográfico muestra un patrón activo reactivo, línea de base de 140 latidos por minuto, variabilidad a corto plazo normal, sin dinámica. Señale la afirmación correcta:', '[{"position": 1, "text": "Ante la sospecha de desprendimiento prematuro de placenta normoinserta, indica cesárea urgente."}, {"position": 2, "text": "Ante la sospecha de placenta previa oclusiva total, indica finalización de la gestación mediante cesárea."}, {"position": 3, "text": "Ante la sospecha de desprendimiento prematuro de placenta normoinserta, indica finalización mediante parto vaginal dado que el monitor es tranquilizador."}, {"position": 4, "text": "Ante la sospecha de una rotura uterina, indica cesárea urgente."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-069', 'ee405649a2df21130b7a285169ec161afdff98f7', 2024, 0, 69, false, false, 'Ginecología y Obstetricia', NULL, 'A una de sus pacientes, primigesta, se le ha practicado una ecografía de rutina a las 20 semanas de gestación que ha detectado un mioma en su útero que parece haber crecido bastante respecto a las previas. Está muy preocupada por las posibles secuelas que este tumor pueda tener en el resultado de su embarazo. Usted le informa de que todas las siguientes complicaciones pueden ocurrir en el embarazo como consecuencia de los miomas uterinos, EXCEPTO:', '[{"position": 1, "text": "Necrosis y degeneración de los miomas."}, {"position": 2, "text": "Malposición fetal."}, {"position": 3, "text": "Progresión a leiomiosarcoma."}, {"position": 4, "text": "Parto pretérmino."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-070', '2f1efba98b09f840e145ca2aec57edacb5025765', 2024, 0, 70, false, false, 'Ginecología y Obstetricia', NULL, 'Gestante de 29 semanas remitida por sospecha de crecimiento intrauterino restringido (CIR). En la ecografía se observa un peso fetal estimado en el percentil 1 con Doppler de la arteria umbilical con onda de velocidad de flujo con diástole revertida. ¿En qué momento se aconseja la finalización de la gestación ?:', '[{"position": 1, "text": "Se trata de un feto pequeño para la edad gestacional: finalización a las 40 semanas."}, {"position": 2, "text": "Se trata de un feto CIR tipo 1: finalización a las 37 semanas."}, {"position": 3, "text": "Se trata de un feto CIR tipo 2: finalización a las 34 semanas."}, {"position": 4, "text": "Se trata de un feto CIR tipo 3: finalización a las 30 semanas."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-071', '45182de3618e193f444de0533d40aa1c698a08e0', 2024, 0, 71, false, false, 'Ginecología y Obstetricia', NULL, 'Acude al servicio de urgencias una puérpera de 32 años (con un parto eutócico hace 2 meses e instauración adecuada de lactancia materna) que presenta dolor, enrojecimiento y calor en la mama derecha, junto con malestar general y un pico febril único de 38 ℃. ¿ Cuál de las siguientes es la actitud más apropiada ?:', '[{"position": 1, "text": "Retirada de la lactancia con cabergolina y administrar probióticos orales, como el Lactobacillus fermentum, durante 1 mes."}, {"position": 2, "text": "Antibioticoterapia oral, junto con el vaciado adecuado de la mama."}, {"position": 3, "text": "Retirada de la lactancia con cabergolina y antibioticoterapia oral."}, {"position": 4, "text": "Antibióticos locales, junto con lavados de la mama con antisépticos."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-072', '10bb4ac4c691ac54b1debe8cc7f431fd6c20959c', 2024, 0, 72, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer de 35 años sin antecedentes de interés, nuligesta, que acude a urgencias por sangrado entre reglas en cantidad moderada que afecta a su calidad de vida. Además refiere que últimamente tiene reglas mucho más abundantes. El hemograma y la coagulación son normales. En la ecografía ginecológica se observa útero en ante, regular, de 58x35 mm, con endometrio en fase proliferativa, nódulo hipoecoico en cara anterior uterina con Doppler periférico de alta resistencia (sin Doppler central) de 28x29 mm compatible con un leiomioma tipo 1 (clasificación de la FIGO 2011), anejos normales, no líquido libre en Douglas. Señale la actitud más correcta:', '[{"position": 1, "text": "Le explica los hallazgos y descarta que el leiomioma, dada la localización, sea la causa de sus sangrados."}, {"position": 2, "text": "Le explica que el leiomioma es probablemente la causa de los sangrados y la deriva a la consulta de histeroscopias."}, {"position": 3, "text": "Le explica que el leiomioma es probablemente la causa de los sangrados y la deriva a la consulta de ginecología para programar una miomectomía por laparoscopia."}, {"position": 4, "text": "Dados los hallazgos ecográficos, solicita resonancia magnética preferente, pauta un análogo de la GnRH y revisión en consulta."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-073', '9b708b602c80fc38ae90d76647daa50c78dee60a', 2024, 0, 73, false, false, 'Enfermedades Infecciosas', NULL, 'En relación con la tos ferina producida por la Bordetella pertussis señale la afirmación correcta:', '[{"position": 1, "text": "En la exploración clínica de la tos ferina es habitual la presencia de sibilancias en la auscultación pulmonar."}, {"position": 2, "text": "La azitromicina es el antibiótico de elección para el tratamiento en todos los grupos de edad."}, {"position": 3, "text": "El \"gallo\" (esfuerzo inspiratorio masivo) se produce fundamentalmente en los niños menores de 2 meses de edad."}, {"position": 4, "text": "Los vómitos posteriores al episodio paroxístico de tos son extremadamente raros."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-074', '8d543e95c8874a7c89efd0f877778ccce2eea0f2', 2024, 0, 74, false, false, 'Pediatría', NULL, 'Niño de 8 años, atendido por dolor abdominal de 2 días de evolución. La noche anterior presentó una deposición con sangre. Esta mañana se ha levantado con dolor en ambos tobillos, no quiere andar y le han visto unas manchas en las piernas. A la exploración presenta buen estado general, auscultación normal, abdomen doloroso a la palpación sin signos irritación peritoneal. En la esfera ORL solo se aprecia una faringe roja. Presenta lesiones petequiales y equímosis en ambas piernas con inflamación de ambos tobillos. El diagnóstico clínico más probable con los datos aportados es:', '[{"position": 1, "text": "Púrpura de Schönlein-Henoch."}, {"position": 2, "text": "Sarampión."}, {"position": 3, "text": "Enfermedad de Kawasaki."}, {"position": 4, "text": "Escarlatina."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-075', 'bad8b289b2bce4b6b3854064f682968ad49f48c0', 2024, 0, 75, false, false, 'Nefrología', NULL, 'El síndrome hemolítico-urémico es una de las causas más frecuentes de insuficiencia renal aguda en niños pequeños. Se caracteriza típicamente por todo lo siguiente, EXCEPTO:', '[{"position": 1, "text": "Anemia hemolítica microangiopática."}, {"position": 2, "text": "Trombocitopenia."}, {"position": 3, "text": "Alargamiento de los tiempos de coagulación (TPTA y protrombina)."}, {"position": 4, "text": "Puede desencadenarlo una infección previa por Streptococcus pneumoniae."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-076', 'c836af1975806d7070b01c5fd944575cb5910dd9', 2024, 0, 76, false, false, 'Pediatría', NULL, 'La puntuación de Apgar es un método práctico en la valoración del recién nacido. Incluye todos los siguientes signos EXCEPTO uno. ¿ Cuál ?:', '[{"position": 1, "text": "Frecuencia cardiaca."}, {"position": 2, "text": "Frecuencia respiratoria."}, {"position": 3, "text": "Tono muscular."}, {"position": 4, "text": "Color."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-077', '6eb573d3488ae1d86f13bd76398b39df17664771', 2024, 0, 77, false, false, 'Pediatría', NULL, 'Paciente de 2 años con fiebre, conjuntivitis, rinorrea y tos repetitiva. Su estado vacunal es desconocido. En la exploración presenta en la mucosa oral, a la altura de los premolares, puntos de color blanco azulado rodeados de un halo eritematoso. ¿ Cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Enfermedad de Kawasaki."}, {"position": 2, "text": "Escarlatina."}, {"position": 3, "text": "Rubeola."}, {"position": 4, "text": "Sarampión."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-078', 'f497dcc339d09bc6d99b11627e0451d14d079d47', 2024, 0, 78, false, false, 'Pediatría', NULL, 'Paciente de 3 años que acude a urgencias de un hospital. En el triángulo de evaluación pediátrica muestra alteración de 2 lados: apariencia y circulatorio. En la exploración destaca una presión arterial de 60/30 mmHg y un exantema eritematoso macular generalizado. Los exámenes complementarios muestran elevación de urea y creatinina, alargamiento del tiempo de protrombina, fibrinogeno bajo, plaquetas 50.000/mm3 y elevación de transaminasas. En el hemocultivo se aísla estreptococo del grupo A. ¿Cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Fascitis estreptocócica."}, {"position": 2, "text": "Glomerulonefritis postestreptocócica."}, {"position": 3, "text": "Shock tóxico estreptocócico."}, {"position": 4, "text": "Escarlatina."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-079', 'a1a5b7baed2437e6cd4579d22ad20ccbb5eb2d9b', 2024, 0, 79, false, false, 'Pediatría', NULL, 'Niña de 10 años que presenta en un análisis una importante elevación de transaminasas, que persiste en controles posteriores. Entre los estudios complementarios destaca la presencia en sangre de anticuerpos antimicrosómicos de hígado-riñón tipo 1 (anti-LKM-1). El cuadro que presenta tiene todas las características siguientes, EXCEPTO una de las siguientes:', '[{"position": 1, "text": "Hipogammaglobulinemia."}, {"position": 2, "text": "En la biopsia hepática presentará una típica hepatitis de interfase."}, {"position": 3, "text": "Es más frecuente en el sexo femenino."}, {"position": 4, "text": "Se trata de una hepatitis autoinmune tipo 2."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-080', '51368cf53822ffd84dd25db819ed6af403560350', 2024, 0, 80, false, false, 'Endocrinología', NULL, 'Niña de 18 meses procedente de un país africano que acaba de ser adoptada y es atendida en consulta para un examen de salud. En la analítica se observan unos niveles de vitamina D muy bajos. Respecto a este hallazgo ¿cuál es el dato exploratorio menos probable ?:', '[{"position": 1, "text": "Persistencia de fontanela anterior."}, {"position": 2, "text": "Ensanchamiento de muñecas y rodillas."}, {"position": 3, "text": "Hepatomegalia."}, {"position": 4, "text": "Genu valgo."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-081', '6be68c6b070a71ad1a0a646944d7b7e0aaf36e97', 2024, 0, 81, false, false, 'Pediatría', NULL, 'Acerca de la bronquiolitis aguda en la infancia, señale la respuesta correcta:', '[{"position": 1, "text": "El virus respiratorio sincitial (VRS) es la segunda causa de bronquiolitis aguda y neumonía vírica en menores de 1 año."}, {"position": 2, "text": "Se recomienda la administración de palivizumab para proteger a niños con riesgo alto contra las complicaciones graves de la enfermedad por el VRS."}, {"position": 3, "text": "La bronquiolitis se produce por obstrucción y colapso de las vías respiratorias de mediano y gran calibre durante la espiración."}, {"position": 4, "text": "El tratamiento se basa en aerosoles de suero salino hipertónico, adrenalina y/o beta-2 agonistas según la gravedad."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-082', '869c125b3f551095e2d1b882d471173cfd533965', 2024, 0, 82, false, false, 'Psiquiatría', NULL, 'La base neurobiológica fundamental de la bulimia nerviosa, en que se apoya también su tratamiento farmacológico habitual, consiste en una disfunción de la neurotransmisión:', '[{"position": 1, "text": "Serotoninérgica."}, {"position": 2, "text": "Dopaminérgica."}, {"position": 3, "text": "Histaminérgica."}, {"position": 4, "text": "Colinérgica."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-083', '57459a7c6ae654d8ab94d135c5a2089dd0b668ba', 2024, 0, 83, false, false, 'Psiquiatría', NULL, 'Hombre de 33 años, soltero, vive en pareja desde hace 10 años. Operario de profesión. Muy buena relación con su familia de origen, cierta dependencia emocional de la madre. Desde hace un año presenta un aumento de preocupación por cualquier aspecto de su vida y está muy inquieto y en ocasiones irritable. Se siente agotado, tenso y enfermo, por lo que el último año ha acudido un par de veces a urgencias. Además, tiene sensación de falta de control, rumiaciones, ansiedad anticipatoria, tristeza y apatía. El cuadro clínico se inició cuando la empresa en la que trabaja inició un expediente de regulación de empleo. ¿ Cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Trastorno distímico."}, {"position": 2, "text": "Trastorno de ansiedad generalizada."}, {"position": 3, "text": "Episodio depresivo mayor."}, {"position": 4, "text": "Trastorno por somatización."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-084', 'd975daac131ed8b469f7f4abf5dad49d17f7337c', 2024, 0, 84, false, false, 'Neurología y Neurocirugía', NULL, 'Mujer de 87 años que padece una enfermedad de Alzheimer en grado moderado e hipertensión arterial. Sufre también una incontinencia de orina que se ha ido agravando en las últimas semanas, para la que se le ha prescrito recientemente un fármaco anticolinérgico (oxibutinina). ¿ Qué problema puede desencadenar con más frecuencia la toma de este fármaco ?:', '[{"position": 1, "text": "La aparición de delirium."}, {"position": 2, "text": "La aparición de bloqueo aurículo-ventricular."}, {"position": 3, "text": "La aparición de crisis hipertensivas."}, {"position": 4, "text": "La aparición de un síndrome de Sjögren."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-085', '3270c48bd54032e30ca90890f8266f8eaf7e12f2', 2024, 0, 85, false, false, 'Psiquiatría', NULL, 'Con respecto a la epidemiología de la esquizofrenia, señale la afirmación correcta:', '[{"position": 1, "text": "Su edad máxima de aparición es a los 40 años."}, {"position": 2, "text": "El inicio precoz es mas frecuente en varones."}, {"position": 3, "text": "Al tratarse de una enfermedad del neurodesarrollo, la importancia de los factores psicosociales en su aparición es despreciable."}, {"position": 4, "text": "Las personas que la padecen tienen una probabilidad de 2 a 3 veces menor de morir prematuramente que la población general."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-086', '4022481f4b3a74a4905bff3656e23546f2d7f65d', 2024, 0, 86, false, false, 'Psiquiatría', NULL, 'Médico de 50 años que con frecuencia acumula retraso de 2 horas en la consulta, creando algún conflicto, aunque es el que tiene menor cupo de pacientes. Empieza su jornada laboral antes de la hora para planificar y adelantar su trabajo, pero siempre es el último en salir. Explica: "no soporto dejar algo a medias, soy muy perfeccionista, tengo muchas cosas que hacer además de las visitas (burocracia, papeleos) y no tengo tiempo para nada más. No sé cómo lo hacen mis compañeros que tienen familia, aficiones ... Yo no tengo tiempo ni para ir al gimnasio. Los fines de semana me quedo en casa, descansando. No tengo vida social." A la exploración se aprecia una preocupación por los detalles, el orden y las normas, una incapacidad para discernir lo que es urgente y prioritario de lo que no lo es, una conducta inflexible y una incapacidad para delegar. ¿ Cuál de las siguientes sería la orientación diagnóstica ?:', '[{"position": 1, "text": "Trastorno esquizoide de la personalidad."}, {"position": 2, "text": "Trastorno narcisista de la personalidad."}, {"position": 3, "text": "Trastorno obsesivo-compulsivo de la personalidad."}, {"position": 4, "text": "Trastorno de la personalidad no especificado."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-087', '3003a69b358dd68f71ee476c1bded4e4b3839667', 2024, 0, 87, false, false, 'Psiquiatría', NULL, 'Sobre el tratamiento farmacológico de la manía aguda en el trastorno bipolar, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El litio es igual o ligeramente más eficaz que el valproato."}, {"position": 2, "text": "Los antipsicóticos son efectivos tanto en monoterapia como en asociación con eutimizantes."}, {"position": 3, "text": "El litio muestra una eficacia similar a los antipsicóticos, aunque con un inicio de acción más rápido."}, {"position": 4, "text": "No existe un antipsicótico de elección en el tratamiento."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-088', 'ae078abd93cd23df35d0687a865e358fbeeea492', 2024, 0, 88, false, false, 'Psiquiatría', NULL, 'Los criterios DSM-5 para el diagnóstico de un trastorno depresivo mayor requieren la presencia de al menos uno de dos de los síntomas principales de la enfermedad. ¿ Cuál de los siguientes es uno de esos síntomas principales ?:', '[{"position": 1, "text": "Agitación."}, {"position": 2, "text": "Insomnio."}, {"position": 3, "text": "Anergia."}, {"position": 4, "text": "Anhedonia."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-089', '7f072f823094e487f70caa60cb6ee66f2ec4728b', 2024, 0, 89, false, false, 'Psiquiatría', NULL, 'Valoramos en urgencias a una persona adulta que se encuentra irritable, bostezando, con quejas de dolor muscular y calambres. Está nauseosa y tiene lagrimeo llamativo. Las pupilas están midriáticas. ¿Cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Intoxicación por benzodiazepinas."}, {"position": 2, "text": "Abstinencia de opiáceos."}, {"position": 3, "text": "Intoxicación por cannabis."}, {"position": 4, "text": "Abstinencia de alcohol."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-090', 'd718500a525d708df7e34a2f8a176559a083c319', 2024, 0, 90, false, false, 'Enfermedades Infecciosas', NULL, 'Niño de 7 años que acude a urgencias por un cuadro de 12 horas de evolución de fiebre, cefalea, rigidez de nuca y petequias en tronco y piernas, con importante afectación del estado general. ¿Cuál de las siguientes afirmaciones es correcta ?:', '[{"position": 1, "text": "Es esperable encontrar diplococos grampositivos en el líquido cefalorraquídeo."}, {"position": 2, "text": "La etiología mas probable es el neumococo."}, {"position": 3, "text": "Será necesario hacer quimioprofilaxis en las personas que hayan estado en contacto íntimo con el paciente."}, {"position": 4, "text": "El tratamiento empírico inicial más apropiado es el aciclovir."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-091', 'c9fa95c57179814fcc8c6fabba4b194c38c33f55', 2024, 0, 91, false, false, 'Neurología y Neurocirugía', NULL, 'Dentro de la exploración neurólogica el término astereognosia hace referencia a:', '[{"position": 1, "text": "La incapacidad de reconocer la forma, el tamaño, el peso y la textura de un objeto por la palpación a ciegas, siendo normales las sensibilidades básicas."}, {"position": 2, "text": "La incapacidad de localizar en el cuerpo un estímulo táctil superficial."}, {"position": 3, "text": "La pérdida de la capacidad sensitiva de discriminación entre dos estímulos simultáneos que habitualmente reconocen como independientes."}, {"position": 4, "text": "La situación que se da cuando se estimula de manera simultánea en dos puntos simétricos y solo se percibe uno de los estímulos."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-092', '2a842640a0047ac1e3ea0e4da5703f305f6e06d1', 2024, 0, 92, false, false, 'Neurología y Neurocirugía', NULL, 'Mujer de 50 años que refiere dificultad para conciliar el sueño por intraquilidad y parestesias en las piernas. La exploración física y neurológica es normal. Su tratamiento NO debería incluir:', '[{"position": 1, "text": "Metilfenidato."}, {"position": 2, "text": "Suplementos de hierro, en caso de ferrropenia."}, {"position": 3, "text": "Agonistas dopaminérgicos."}, {"position": 4, "text": "Pregabalina."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-093', '701882091eda7868839cd4b96679351b7c874b0e', 2024, 0, 93, false, false, 'Neurología y Neurocirugía', NULL, 'Hombre de 67 años con deterioro brusco del nivel de conciencia, encontrándose obnubilado. Presenta alteración visual, con ptosis y midriasis del ojo derecho asociados a pérdida de visión en ojo derecho, sólo cuenta dedos con ojo izquierdo. La TC craneal muestra una lesión hemorrágica que agranda y deforma la silla turca, con cierta extensión supraselar. En relación con este cuadro clínico, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El tratamiento quirúrgico por vía endoscópica transnasal urgente podría mejorar el pronóstico visual y de afectación de pares."}, {"position": 2, "text": "Suele cursar con hiperfunción hormonal."}, {"position": 3, "text": "Este cuadro clínico puede aparecer también en mujeres tras el parto."}, {"position": 4, "text": "Suele producirse cuando de base hay una tumoración previa."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-094', '2bc3c54d8d32fcbb04cb9426ad5a1ae9698c2451', 2024, 0, 94, false, false, 'Neurología y Neurocirugía', NULL, 'Adolescente de 15 años que comienza con crisis mioclónicas, sobre todo en los brazos, más frecuentes al despertar, que suelen aparecer tras la privación del sueño o la ingesta de alcohol. Tras las mioclonias presenta algunas veces una crisis convulsiva generalizada. En el EEG se objetivan complejos de punta-onda y polipunta-onda con gran fotosensibilidad. De los siguientes ¿cuál sería el fármaco antiepiléptico más indicado para comenzar el tratamiento ?:', '[{"position": 1, "text": "Clonazepam."}, {"position": 2, "text": "Carbamazepina."}, {"position": 3, "text": "Etosuximida."}, {"position": 4, "text": "Ácido valproico."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-095', 'b4b22cbc24b41b255f620ce4976885b67f2690d4', 2024, 0, 95, false, false, 'Neurología y Neurocirugía', NULL, 'Mujer de 45 años que presenta un dolor de características lancinantes en hemicara derecha. El dolor se despierta al tocarse, lavarse o cepillarse los dientes. No le duele por la noche. Señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El tratamiento más efectivo es la descompresión quirúrgica si existe contacto neurovascular."}, {"position": 2, "text": "La carbamazepina sigue siendo el tratamiento de elección."}, {"position": 3, "text": "Tanto la radiocirugía como los procedimientos ablativos (p.ej. radiofrecuencia) tienen riesgo de recidiva."}, {"position": 4, "text": "Es frecuente la pérdida de sensibilidad asociada al dolor."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-096', 'f6f0016064f82ae5e98aa71b9775fca4347f90d5', 2024, 0, 96, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 59 años que ingresa en UCI por insuficiencia respiratoria aguda hipoxémica secundaria a neumonía comunitaria grave. Por fracaso respiratorio, precisa sedación y conexión a ventilación mecánica invasiva. Tiene como antecedente laboral el trabajar en una granja de cerdos, por lo que empíricamente se decide cubrir un estafilococo aureus meticilin resistente hasta tener los cultivos de las secreciones respiratorias. ¿Cuál de los siguientes antibióticos iniciaría empíricamente como monoterapia antimicrobiana ?:', '[{"position": 1, "text": "Piperacilina-tazobactam."}, {"position": 2, "text": "Ceftarolina."}, {"position": 3, "text": "Cefazolina."}, {"position": 4, "text": "Cefotaxima."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-097', 'fc3e0211e60e89961cd7ca986a3d917b724f63e4', 2024, 0, 97, false, false, 'Psiquiatría', NULL, '¿Cuál de los siguientes fármacos se asocia a una reducción del delirium en las unidades de cuidados intensivos ?:', '[{"position": 1, "text": "Cisatracurio."}, {"position": 2, "text": "Dexmedetomidina."}, {"position": 3, "text": "Midazolam."}, {"position": 4, "text": "Venlafaxina."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-098', '3a4796a0c907effc68d575b2d8313d493c0c508d', 2024, 0, 98, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 62 años sin antecedentes de interés y profesión sedentaria, que consulta por dolor muy intenso, incapacitante, en región lumbar, de 1 semana de evolución, irradiado a nalga, cara posterior de muslo izquierdo y cara anterolateral de pierna izquierda. El signo de Lasègue es negativo y no presenta déficit de fuerza en las extremidades inferiores. La actitud terapéutica más adecuada, de entre las siguientes, es:', '[{"position": 1, "text": "Remitir de forma urgente a neurocirugía para pruebas de imagen y valoración quirúrgica."}, {"position": 2, "text": "Realizar radiografía y resonancia magnética urgentes de raquis lumbar."}, {"position": 3, "text": "Pautar un antiinflamatorio no esteroideo a dosis alta, evitar el reposo en cama, calor local suave y revisión en 2 semanas."}, {"position": 4, "text": "Solicitar un electromiograma preferente de extremidades inferiores."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-099', '90c7823e43d91b7687d2b49b0681c49b5effe015', 2024, 0, 99, false, false, 'Reumatología', NULL, 'Cuidadora de personas mayores de 55 años, sin antecedentes de interés, diestra, que refiere dolor y acorchamiento en cara palmar de ambas manos, peor en la derecha, con predominio nocturno, así como sensación de gran hinchazón al despertarse por las mañanas, siendo algo más intenso en los dedos 2º y 3º. No refiere ningún otro síntoma en miembros superiores ni en cuello. ¿ De las siguientes, cuál es la primera sospecha diagnóstica ?:', '[{"position": 1, "text": "Espondiloartrosis cervical C5-C6."}, {"position": 2, "text": "Compresión cubital epitroclear."}, {"position": 3, "text": "Hernia discal cervical C6-C7."}, {"position": 4, "text": "Síndrome del túnel carpiano."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-100', 'a97df58f0b0fccebb561a54bb7fdb82af2c86749', 2024, 0, 100, false, false, 'Pediatría', NULL, 'Neonato de 3 semanas que presenta un reflejo de Moro asimétrico. Parto vaginal de madre primímara, peso al nacer 4.600 g. Se palpa un bulto en la clavícula derecha y mantiene el hombro derecho en aducción, con el codo extendido y flacidez de muñeca y dedos de la mano derecha. En la radiografía de tórax realizada al nacer se observa una elevación del hemidiafragma derecho. Es signo de mal pronóstico la existencia de:', '[{"position": 1, "text": "Ausencia de contracción del bíceps a esta edad."}, {"position": 2, "text": "Una fractura de clavícula ipsilateral."}, {"position": 3, "text": "Un síndrome de Horner ipsilateral."}, {"position": 4, "text": "Una luxación congénita de la cadera ipsilateral."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2024-v0-101', '4108a1b4584afb411a8bb86d3ca001c6a359ca81', 2024, 0, 101, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Mujer de 52 años, carnicera de profesión, sin antecedentes de interés ni caídas, que presenta dolor en el hombro de 4 meses de evolución al levantar el brazo. El dolor es de características inflamatorias y las maniobras de impingement positivas. Señale la actitud INCORRECTA:', '[{"position": 1, "text": "Iniciar tratamiento con AINE, solicitar una ecografía y derivar a rehabilitación"}, {"position": 2, "text": "Derivar a un cirujano especialista para hacer una artroscopia de hombro."}, {"position": 3, "text": "Si hay limitación pasiva del balance articular, con la sospecha de capsulitis adhesiva, derivar a rehabilitación urgente para movilizaciones pasivas."}, {"position": 4, "text": "Se sospecha una lesión del manguito de los rotadores (supraespinoso con bursitis subacromial), por lo que hay que potenciar la musculatura descoaptante del hombro."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-102', '64f5d0c1a9acfa64d1ff208ec0892713518da0ef', 2024, 0, 102, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Acude de nuevo a urgencias una mujer de 67 años que ayer fue tratada de una fractura del extremo distal del radio izquierdo mediante reducción cerrada bajo anestesia focal y yeso antebraquial. Aqueja dolor insoportable, que aumenta cuando se le mueven los dedos; efectivamente es incapaz de movilizar activamente los dedos y estos están muy hinchados. ¿ Qué complicación debemos tratar inmediatamente ?:', '[{"position": 1, "text": "Síndrome de dolor regional complejo."}, {"position": 2, "text": "Síndrome compartimental local."}, {"position": 3, "text": "Rotura tendinosa de extensores."}, {"position": 4, "text": "Desplazamiento secundario de la fractura."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-103', 'fee9c3f1b3231dcd912dc5f3fadb5c1dff36595b', 2024, 0, 103, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Paciente de 27 años que sufre un accidente de alto impacto con patinete eléctrico en la calle. A la llegada a urgencias está consciente y orientado, Glasgow 15, con tendencia a la hipotensión. En la exploración inicial presenta impotencia funcional con un balance muscular segun Daniels de 5 en todos los grupos de extremidades superiores. En extremidades inferiores psoas 5, cuadriceps 3, tibial anterior, triceps sural y extensores del dedo gordo 0 bilateral. De las siguientes, la sospecha diagnóstica inicial es:', '[{"position": 1, "text": "Fractura-luxación de C7-T1"}, {"position": 2, "text": "Fractura estallido de L2 con afectación neurológica."}, {"position": 3, "text": "Isquemia medular lumbar secundaria al traumatismo."}, {"position": 4, "text": "Fractura estallido de T12 con afectación medular completa."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-104', 'e18652a89146438834cbae115dbf23b8ed2f621f', 2024, 0, 104, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Paciente de 73 años activo, que presenta dolor de intensidad EVA 8-9 en el hombro derecho (miembro dominante) con pérdida de movilidad. Se realiza una radiografía y una RM que muestran una rotura completa del manguito rotador con ascenso de la cabeza humeral y erosión (acetabulización) del borde inferior del acromion. ¿Cuál de las siguientes es la actitud terapéutica más adecuada ?:', '[{"position": 1, "text": "Prótesis anatómica de hombro."}, {"position": 2, "text": "Infiltración del resto de manguito con células mesenquimales."}, {"position": 3, "text": "Reparación artroscópica del manguito rotador mediante anclajes en doble hilera."}, {"position": 4, "text": "Prótesis invertida de hombro."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-105', '9f684633ce8510318bb0bc2c030364db2ade1fa5', 2024, 0, 105, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Mujer de 56 años que consulta porque hace 4 meses se torció el tobillo en la playa y desde entonces no ha dejado de molestarle. Se cansa subiendo escaleras y le cuesta usar calzado plano. En la exploración presenta dolor en el seno del tarso, el talón y la cara medial del tobillo. Al examen podoscópico presenta el talón en valgo, aunque corrige de puntillas. La estructura más probablemente afecta es:', '[{"position": 1, "text": "El tendón del músculo tibial posterior."}, {"position": 2, "text": "El ligamento peroneo-astragalino anterior."}, {"position": 3, "text": "El tendón del músculo flexor largo del dedo gordo."}, {"position": 4, "text": "El ligamento intertalocalcáneo."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-106', '045adb70b0c2bcfa9a9a30efa1e79ce5fbff4da6', 2024, 0, 106, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Niña de 12 años sin antecedentes relevantes, con menarquia hace 4 meses, que acude a la consulta de rehabilitación derivada por su pediatra tras encontrar una asimetría de hombros en la revisión anual. En la exploración física presenta una asimetría de la altura de los hombros y de las caderas con test de Adams positivo. De las siguientes, la actitud correcta a seguir es:', '[{"position": 1, "text": "Solicitar un escoliograma en bipedestación y en función de los grados de Cobb decidir tratamiento con corsé."}, {"position": 2, "text": "Proponer una revisión en 6 meses con un escoliograma en decúbito."}, {"position": 3, "text": "Derivar a fisioterapia para estiramientos y masajes del raquis."}, {"position": 4, "text": "Recomendar natación para corregir y revisión en 6 meses."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-107', '319cac506e755a149c3db5942f4fa6a6d6c8578f', 2024, 0, 107, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Niña de 6 años que estaba celebrando un cumpleaños en un castillo hinchable, cayendo sobre el brazo extendido. Acude a urgencias con dolor y deformidad a nivel del húmero distal derecho e impotencia funcional del codo. A la exploración no se palpa pulso radial, el relleno capilar de los dedos es de 2 segundos y el color de la mano es sonrosado. La actitud mas recomendable es:', '[{"position": 1, "text": "Realizar una arteriografía de la arteria humeral."}, {"position": 2, "text": "Reducir y fijar la fractura en quirófano y observar la respuesta vascular."}, {"position": 3, "text": "Proceder a la exploración quirúrgica de la arteria humeral."}, {"position": 4, "text": "Hacer una ecografía Doppler de la arteria radial a nivel de la muñeca."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-108', '2a3ba8b28d891ac059ab3579ce88453b1eb920fd', 2024, 0, 108, false, false, 'Reumatología', NULL, 'Respecto a las manifestaciones extraarticulares de la artritis reumatoide, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Es la causa más frecuente de síndrome de Sjögren secundario y cursa con queratoconjuntivitis seca."}, {"position": 2, "text": "La manifestación cardiaca más frecuente es la pericarditis."}, {"position": 3, "text": "La pleuritis se caracteriza por un derrame pleural con características de exudado y típicamente con glucosa muy baja."}, {"position": 4, "text": "La manifestación hematológica más frecuente es la leucopenia."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-109', '12dcb16a003210c715ab4b16703f8263055d4d5a', 2024, 0, 109, false, false, 'Hematología', NULL, 'Mujer de 60 años de edad diagnosticada de una enfermedad autoinmune. En la exploración física presenta aumento de tamaño bilateral de parótidas, vasculitis cutánea y test de Schirmer en ojo derecho 2 mm, ojo izquierdo 1 mm (por debajo de lo normal). En la analítica destaca factor reumatoide positivo, VSG 30 mm (1-20), PCR 1,3 (0-0,5), anticuerpos antinucleares positivos con patrón moteado fino, anti Ro y anti La positivos e hipocomplementemia. ¿Cuál de estas enfermedades tiene más riesgo de desarrollar durante la evolución de la enfermedad ?:', '[{"position": 1, "text": "Leucemia linfoblástica aguda."}, {"position": 2, "text": "Linfoma de células B."}, {"position": 3, "text": "Leucemia de células NK."}, {"position": 4, "text": "Linfoma no Hodgkin de células T."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-110', 'bff81e6593b5a220a61ebc548b48ca23ecbce5ab', 2024, 0, 110, false, false, 'Reumatología', NULL, 'Hombre de 50 años que consulta por dolor lumbar de 6 meses de evolución que no mejora con el reposo, incluso le despierta por la noche, con rigidez lumbar matutina de más de una hora de duración. ¿ Cuál de las siguientes imágenes es más probable encontrar en una radiografía de columna lumbar ?:', '[{"position": 1, "text": "Osteofitos típicos de la espondiloartrosis."}, {"position": 2, "text": "Osteofitos típicos de la espondiloartritis."}, {"position": 3, "text": "Sindesmofitos típicos de la espondiloartrosis."}, {"position": 4, "text": "Sindesmofitos típicos de la espondiloartritis."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-111', 'acadbded2fae9ec6ae28e6c6d2e680dd82fdd0bb', 2024, 0, 111, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Paciente de 65 años con antecedentes de un infarto de miocardio de cara anterior que presenta una taquicardia con QRS ancho que se acompaña de hipotensión (TA 70/40 mmHg) y de obnubilación. ¿Cuál de los siguientes es el tratamiento de elección ?:', '[{"position": 1, "text": "Lidocaína IV."}, {"position": 2, "text": "Amiodarona IV."}, {"position": 3, "text": "Procainamida IV."}, {"position": 4, "text": "Cardioversión eléctrica urgente."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-112', '78c3bb49574a35d35fc52be125aa930e457cf5d7', 2024, 0, 112, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Mujer de 58 años que, tras un catarro de vías altas, ingresa en el hospital por disnea de mínimos esfuerzos, astenia intensa y disnea paroxística nocturna en los días previos. El electrocardiograma muestra un ritmo sinusal a 70 Ipm con bloqueo de rama izquierda. En el ecocardiograma transtorácico se aprecia una función ventricular izquierda (FEVI) del 25 %. La coronariografía descarta enfermedad arterial coronaria. De las siguientes propuestas de tratamiento ¿cuál sería la combinación de fármacos recomendada que mejore su pronóstico y reduzca los reingresos hospitalarios por descompensación cardiaca ?:', '[{"position": 1, "text": "Betabloqueante, digoxina, ARNI (inhibidor de neprilisina-receptor angiotensina) e iSGLT2 (inhibidores del cotransportador de sodio-glucosa tipo 2)."}, {"position": 2, "text": "Betabloqueante, antagonistas de la aldosterona, ivabradina e iSGLT2 (inhibidores del cotransportador de sodio-glucosa tipo 2)."}, {"position": 3, "text": "Betabloqueante, antagonistas de la aldosterona, ARNI (inhibidor de neprilisina-receptor angiotensina) y milrinona."}, {"position": 4, "text": "Betabloqueante, antagonistas de la aldosterona, ARNI (inhibidor de neprilisina-receptor angiotensina) 0 iSGLT2 (inhibidores del cotransportador de sodio-glucosa tipo 2)."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-113', '9879e025ff5b16e870d344c2f809407c0a7bd3b9', 2024, 0, 113, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'En relación con la endocarditis infecciosa (EI) señale cuál de las siguientes situaciones tiene indicación de cirugía cardiaca en 24-48 horas:', '[{"position": 1, "text": "Paciente de 82 años con EI por S. mitis sobre prótesis aórtica biológica, con buena evolución clínica, sin dehiscencia valvular, con un pseudoaneurisma de raíz aórtica a la 4º semana de tratamiento antibiótico."}, {"position": 2, "text": "Paciente de 70 años con EI mitral por E. faecalis en el que se evidencia una insuficiencia valvular moderada."}, {"position": 3, "text": "Paciente de 75 años con EI aortica con regurgitación valvular moderada y sin compromiso hemódinámico, con aislamientos repetidos en hemocultivos de Candida albicans sensible a azoles."}, {"position": 4, "text": "Paciente de 68 años con EI aórtica por S. aureus con insuficiencia valvular aórtica moderada- grave y episodio de fracaso ventricular izquierdo con insuficiencia cardiaca grado III de la NYHA durante la primera semana de tratamiento antibiótico."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-114', '383041020d267e48f74716d21f804ed4a45e1255', 2024, 0, 114, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 48 años con antecedentes de hipercolesterolemia y tabaquismo activo. Presenta dolor irradiado centrotorácico a cuello acompañado de náuseas y sudoración profusa de una hora de evolución. El dolor se había iniciado durante el ascenso a una montaña, motivo por el que es trasladado a un centro de salud, donde se le practica un electrocardiograma que muestra un infarto de miocardio agudo anteroseptal. El hospital terciario más cercano (con hemodinámica de guardia 24 h) se encuentra a tres horas de distancia. ¿ En cuál de las siguientes circunstancias DESCARTARÍA la reperfusion coronaria extrahospitalaria mediante fibrinólisis intravenosa y plantearía una angioplastia primaria ?:', '[{"position": 1, "text": "Presencia de signos de insuficiencia cardiaca."}, {"position": 2, "text": "Antecedente de hemorragia craneal sin secuelas hace 10 años."}, {"position": 3, "text": "Antecedente de ictus isquémico hace 18 meses."}, {"position": 4, "text": "Cifras de tensión arterial ≥ 140/90 mmHg."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-115', '82329264077335b4d10d374183af7423063c4f88', 2024, 0, 115, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 70 años sometido hace 5 días a cirugía de revascularización coronaria que acude a urgencias por un síncope tras el que persiste sensación de mareo. En la exploración destaca tensión arterial 70/40 mmHg, ruidos cardiacos disminuidos y distensión venosa yugular con fenómeno de alternancia eléctrica en el electrocardiograma. ¿ Cuál de los siguientes diagnósticos es más probable ?:', '[{"position": 1, "text": "Síndrome coronario agudo."}, {"position": 2, "text": "Pericarditis."}, {"position": 3, "text": "Taponamiento cardiaco."}, {"position": 4, "text": "Endocarditis."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-116', '7dbe42fe9a6ce6db74d36190e6f6dde750080a36', 2024, 0, 116, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'En relación con el prolapso de la válvula mitral, señale la respuesta correcta:', '[{"position": 1, "text": "La degeneración mixomatosa valvular también puede afectar a las válvulas tricúspide y aórtica."}, {"position": 2, "text": "Es más frecuente en hombres."}, {"position": 3, "text": "Tiene un curso benigno y raramente origina insuficiencia valvular mitral."}, {"position": 4, "text": "El soplo cardiaco que puede originar característicamente disminuye de intensidad con la maniobra de Valsalva."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-117', 'e497fdc1a57b64c161e0d619792a0861b26cee95', 2024, 0, 117, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Ante un recién nacido a término cianótico con pO2 de 30 mmHg, hipertrofia de ventrículo derecho en el electrocardiograma e imagen "de huevo" en la radiografía de tórax ¿cuál de los siguientes es el diagnóstico más probable ?:', '[{"position": 1, "text": "Dextro-transposición de grandes arterias."}, {"position": 2, "text": "Persistencia del ductus arterioso."}, {"position": 3, "text": "Tetralogía de Fallot."}, {"position": 4, "text": "Enfermedad de Ebstein."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-118', 'e9661858c98d1c3c810bc3796d8677ec46ead05c', 2024, 0, 118, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Todas las situaciones que se enumeran a continuación se refieren a pacientes con alto riesgo de desarrollar endocarditis infecciosa y por ello con indicación de profilaxis antibiótica ante procedimientos invasivos, EXCEPTO UNA. Señale cual:', '[{"position": 1, "text": "Pacientes portadores de válvula aórtica protésica transcatéter."}, {"position": 2, "text": "Pacientes con cardiopatía congénita cianótica no tratada."}, {"position": 3, "text": "Pacientes con válvula aórtica bicúspide."}, {"position": 4, "text": "Pacientes que han sufrido endocarditis infecciosa previa."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-119', '1fdf0371620ef8b5002ca8235f2eff73d367dd9f', 2024, 0, 119, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 23 años que tras un cuadro gripal acude en situación de shock cardiogénico refractario a aminas a un hospital de 3º nivel. En el ecocardiograma transtorácico se aprecia una fracción de eyección de ventrículo izquierdo del 15 %. Ante la sospecha de miocarditis vírica ¿cuál de las siguientes es la opción terapéutica de elección para mejorar su situación hemodinámica ?:', '[{"position": 1, "text": "Aumentar la dosis de aminas e inclusión en lista urgente para trasplante cardiaco."}, {"position": 2, "text": "Colocación de un balón de contrapulsación intraaórtico."}, {"position": 3, "text": "Implante de un dispositivo electrónico de estimulación biventricular."}, {"position": 4, "text": "Colocación de un dispositivo de asistencia ventricular de corta duración ."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-120', '4f70fa374a40ce511a4a92a29420fb8c59c36051', 2024, 0, 120, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'En relación con el tratamiento de los pacientes con síncope, señale la respuesta correcta:', '[{"position": 1, "text": "El tratamiento del síncope reflejo es fundamentalmente farmacológico."}, {"position": 2, "text": "La estimulación con marcapasos en el síncope recurrente asociado a un mecanismo hipotensor ha demostrado ser eficaz."}, {"position": 3, "text": "Los fármacos betabloqueantes reducen\nla mortalidad de los síncopes reflejos."}, {"position": 4, "text": "Las contracciones musculares isotónicas son útiles en pacientes jóvenes con síncope reflejo y pródromos."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-121', '0f610d8d9f81d5c72240e9feff3354805c806ed3', 2024, 0, 121, false, false, 'Neumología y Cirugía Torácica', NULL, 'En relación con la utilidad de la broncoscopia en el diagnóstico de las enfermedades respiratorias, señale qué afirmación de las siguientes es cierta:', '[{"position": 1, "text": "De todas las técnicas broncoscópicas, la broncoscopia rígida es la más utilizada debido a su mayor seguridad a la hora de proteger la vía aérea."}, {"position": 2, "text": "La criobiopsia tiene mayor rendimiento diagnóstico que la biopsia transbronquial convencional para enfermedades parenquimatosas difusas, pero conlleva un mayor riesgo de hemorragia y neumotórax."}, {"position": 3, "text": "Las adenopatías más facilmente accesibles mediante ultrasonografía endobronquial para el estadiaje del cáncer de pulmón son los ganglios paraesofágicos y los del ligamento pulmonar."}, {"position": 4, "text": "El aspirado bronquial evita el riesgo de contaminación salivar que puede encontrarse en una muestra de esputo y es muy útil cuando se desea tomar muestras de un lóbulo o segmento pulmonar específico."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-122', '3f7044c6a208c9ad270b31cf1ad97fb7eb40343f', 2024, 0, 122, false, false, 'Neumología y Cirugía Torácica', NULL, 'Mujer asmática que tras un día de tormenta presenta sensación disneica y autoescucha de sibilancias. Tras tratamiento inicial con un agonista beta2 y corticoides inhalados no se produjo mejoría de los síntomas, requiriendo broncodilatadores cada hora durante varias horas consecutivas, con aparición de un importante aumento del trabajo respiratorio. De las siguientes ¿cúal es la actitud más adecuada ?:', '[{"position": 1, "text": "Se deben administrar de forma urgente agonistas beta2 nebulizados y, en caso de ausencia de respuesta temprana, añadir corticoides intravenosos."}, {"position": 2, "text": "Antes de iniciarse el tratamiento debe realizase radiografía de tórax, gasometría arterial y analítica general para establecer el diagnóstico."}, {"position": 3, "text": "Los corticoides inhalados estarían contraindicados por aumentar el riesgo de neumonía."}, {"position": 4, "text": "Como primera elección se deben administrar anticolinérgicos nebulizados, debido a la ausencia de respuesta a los agonistas beta2."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-123', '1069e52b67be76898aa149aae3384f6966867afb', 2024, 0, 123, false, false, 'Neumología y Cirugía Torácica', NULL, 'Hombre de 65 años diagnosticado de EPOC con dos agudizaciones en el último año, en tratamiento inhalado con tiotropio. Presenta un volumen espiratorio máximo en el primer segundo (VEMS) del 48 %. Tras estar más de dos meses en situación clínica estable, presenta PaO2 58 mmHg y PaCO2 49 mmHg en la gasometría arterial. En la analítica presenta 450 eosinófilos/microL. No presenta hipertensión pulmonar, cor pulmonale, ni poliglobulia. Con estos datos ¿cuál de las siguientes actuaciones es más apropiada ?:', '[{"position": 1, "text": "Iniciar oxigenoterapia crónica domiciliaria."}, {"position": 2, "text": "Optimizar el tratamiento broncodilatador."}, {"position": 3, "text": "Optimizar el tratamiento broncodilatador e iniciar oxigenoterapia crónica domiciliaria."}, {"position": 4, "text": "Iniciar oxigenoterapia crónica domiciliaria y ventilación mecánica no invasiva domiciliaria."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-124', 'f90828a042b6345ab3980b7a0e4f10b39aca1b2e', 2024, 0, 124, false, false, 'Neumología y Cirugía Torácica', NULL, 'La causa mas frecuente de hipoxemia es:', '[{"position": 1, "text": "Hipoventilación alveolar."}, {"position": 2, "text": "Trastornos de la difusión alveolocapilar de oxígeno."}, {"position": 3, "text": "Cortocircuito intrapulmonar de derecha a izquierda."}, {"position": 4, "text": "Desequilibrio en la relación ventilación- perfusión."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-125', '90d76923fabceac77275e96dec6dab92887031ee', 2024, 0, 125, false, false, 'Neumología y Cirugía Torácica', NULL, 'Hombre de 75 años con antecedentes de insuficiencia cardiaca con fracción de eyección del ventrículo izquierdo del 30 %. Consulta por apneas durante el sueño presenciadas por su pareja. El grado de somnolencia en la escala de Epworth es de 5. El estudio del sueño muestra episodios de respiración periódica con un índice de apneas-hipopneas de 22 por hora de sueño, siendo todos los eventos respiratorios centrales. De las siguientes, la actitud terapéutica recomendada es:', '[{"position": 1, "text": "Iniciar tratamiento con presión positiva continua por vía nasal."}, {"position": 2, "text": "Optimizar el tratamiento de la insuficiencia cardiaca."}, {"position": 3, "text": "Ensayo terapéutico con prótesis de avanzamiento mandibular."}, {"position": 4, "text": "Iniciar tratamiento con servoventilación."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-126', '075f5452474abd25bb936bf65273a952ad7cc1cf', 2024, 0, 126, false, false, 'Neumología y Cirugía Torácica', NULL, 'En relación con la fibrosis pulmonar idiopática, señale cual de las siguientes afirmaciones es cierta:', '[{"position": 1, "text": "La imagen característica de los hallazgos en la TC torácica es la aparición de opacidades en vidrio deslustrado."}, {"position": 2, "text": "Para establecer el diagnóstico se requiere la realización de una biopsia del parénquima pulmonar."}, {"position": 3, "text": "En ocasiones se asocia a enfermedades del tejido conectivo."}, {"position": 4, "text": "La terapia antifibrótica (pirfenidona y nintedanib) puede lentificar el deterioro de la función pulmonar."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-127', 'b7a5738549d268576aa1abecb87886f7a9e5d141', 2024, 0, 127, false, false, 'Neumología y Cirugía Torácica', NULL, 'Mujer de 71 años diagnosticada de esclerosis lateral amiotrófica. Es valorada en consulta por ortopnea y cefalea matutina. Presenta una capacidad vital forzada del 40 %, PaCO2 de 53 mmHg. La oximetría nocturna muestra una saturación de oxígeno media de 91 % y un 16 % del tiempo con saturación de oxigeno inferior al 90 % y alguna desaturación inferior al 70 %. ¿ Cuál de las siguientes actitudes es más apropiada ?:', '[{"position": 1, "text": "Iniciar ventilación mecánica no invasiva."}, {"position": 2, "text": "Realizar controles clínicos sin iniciar un tratamiento concreto en el momento actual."}, {"position": 3, "text": "Iniciar oxigenoterapia por presentar insuficiencia respiratoria nocturna."}, {"position": 4, "text": "Iniciar presión positiva continua (CPAP)."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-128', 'f0d612b0c4679e1c3ef0075be916d1137e16d543', 2024, 0, 128, false, false, 'Neumología y Cirugía Torácica', NULL, 'Paciente de 75 años, fumador (IPA 35), que refiere disnea de esfuerzo progresiva desde hace 3 años. La radiografía de tórax no muestra alteraciones relevantes. En la espirometría basal presenta FVC 1720 mL (62 %), FEV1 610 mL (30 %) y FEV1/FEVC 35 %. ¿ Cual es el diagnóstico de sospecha y la siguiente acción a tomar ?:', '[{"position": 1, "text": "Se trata de una alteración ventilatoria mixta de predominio restrictivo. Para el estudio de las causas se debe realizar estudio funcional completo."}, {"position": 2, "text": "e puede establecer el diagnóstico de enfermedad pulmonar obstructiva crónica. Se debe solicitar TC torácica para confirmar la existencia de enfisema."}, {"position": 3, "text": "Se trata de una alteración ventilatoria mixta con un componente obstructivo grave. Probable EPOC en la que, una vez confirmada la ausencia de reversibilidad, se puede iniciar tratamiento con corticoides inhalados."}, {"position": 4, "text": "Presenta una alteración ventilatoria mixta con componente obstructivo grave que sugiere EPOC. Una vez confirmada la ausencia de reversibilidad, se puede iniciar tratamiento broncodilatador."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-129', '499e519e6917921ad70991cbe45bea4ce8c01be6', 2024, 0, 129, false, false, 'Miscelánea', NULL, 'En relación con la antisepsia del campo quirúrgico en una laparotomía de piel indemne por cirugía oncológica, ¿qué solución de las siguientes ha demostrado ser más eficaz ?:', '[{"position": 1, "text": "Povidona iodada."}, {"position": 2, "text": "Clorhexidina acuosa."}, {"position": 3, "text": "Clorhexidina alcohólica."}, {"position": 4, "text": "Poli-hexametilen-biguanida."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-130', 'cff57b7809972b1bd2f7770501a19112526ad47a', 2024, 0, 130, false, false, 'Aparato Digestivo', NULL, 'Paciente diabético de 50 años que acude a urgencias con fiebre de 39℃ y malestar general que refiere dolor anal desde hace 5 días. A la exploración destaca una gran tumoración perianal caliente y dolorosa, con necrosis de piel. El tratamiento de elección es:', '[{"position": 1, "text": "Drenaje-desbridamiento quirúrgico."}, {"position": 2, "text": "Antibiótico de amplio espectro y esperar evolución."}, {"position": 3, "text": "Ingreso hospitalario para estudio."}, {"position": 4, "text": "Punción-drenaje guiado por radiología."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-131', 'c88c88bbd6dfe249e568a18e4bd375a034f76daf', 2024, 0, 131, false, false, 'Aparato Digestivo', NULL, 'Mujer de 24 años que consulta por un cuadro de dolor abdominal, astenia, diarrea de larga evolución con rectorragia ocasional y pérdida de 10 Kg de peso en 3 meses. En la exploración destacan signos de desnutrición, dolor abdominal difuso con mayor focalidad en fosa ilíaca derecha. En la analítica destacan una hemoglobina baja y una elevación de la PCR. En la colonoscopia se encuentran úlceras aftosas, inflamación segmentaria y un área de estenosis infranqueable, todo ello en ciego. La enterorresonancia confirma este hallazgo y la existencia de inflamación en íleon distal. El cuadro es refractario al tratamiento farmacológico, por lo que se considera la cirugía. De las siguientes, señale la técnica quirúrgica más adecuada:', '[{"position": 1, "text": "Hemicolectomía derecha ampliada."}, {"position": 2, "text": "Panproctocolectomía con reservorio en J."}, {"position": 3, "text": "Ileocequectomía."}, {"position": 4, "text": "Colostomía terminal."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-132', '8a9bc9c1a57b1eea9c80c23aa2e5ae2765a80d52', 2024, 0, 132, false, false, 'Aparato Digestivo', NULL, 'Mujer de 73 años que acude a urgencias por prurito, ictericia, astenia y pérdida de peso de un mes de evolución. Recientemente ha recibido tratamiento con amoxicilina/clavulanico por una infección urinaria. Se realiza una ecografía que informa de dilatación de la vía biliar intra y extrahepática con vesícula biliar distendida. De las siguientes ¿cuál es la primera sospecha diagnóstica y actitud ?:', '[{"position": 1, "text": "Toxicidad por fármacos. Retirada del antibiótico."}, {"position": 2, "text": "Colecistitis aguda. Colecistectomía urgente."}, {"position": 3, "text": "Coledocolitiasis distal. Solicitar una colangiorresonancia magnética."}, {"position": 4, "text": "Tumoración maligna obstructiva de colédoco distal. Solicitar una TC abdominal para estudio de extensión local y a distancia."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-133', 'cef90645a71a970d3b5648663dac707d5ff5d505', 2024, 0, 133, false, false, 'Aparato Digestivo', NULL, 'En un paciente con esteatosis hepática metabólica (antes enfermedad hepática por depósito de grasa) el riesgo de desarrollo de hepatocarcinoma en comparación con otras etiologías frecuentes como la hepatopatía alcohólica o la hepatitis C, se caracteriza por:', '[{"position": 1, "text": "Aparecer en personas más jóvenes."}, {"position": 2, "text": "Se beneficia de los programas de diagnóstico precoz."}, {"position": 3, "text": "Aparece más fecuentemente en fases previas a la cirrosis."}, {"position": 4, "text": "Presenta una incidencia acumulada anual mayor que en la hepatitis C."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-134', 'cb95961a158dfe9e8c943d6cc78b6094ed2d736a', 2024, 0, 134, false, false, 'Aparato Digestivo', NULL, 'Mujer de 62 años que consulta por dolor abdominal persistente, pérdida de peso no intencionada de 10 kg en los últimos tres meses, ictericia y acolia. En las últimas horas presenta vómitos de retención gástrica. Las analíticas muestran elevación de bilirrubina y enzimas hepáticas así como hipopotasemia. La TC abdominal revela una masa en la cabeza del páncreas y proceso uncinado que provoca obstrucción de la vía biliar, infiltración inextirpable vascular, distensión y retención gástrica. Tras estabilizarla se efectúa ecoendoscopia con biopsia que demuestra la existencia de un adenocarcinoma pancreático con estenosis infranqueable del duodeno. ¿ Cuál de las siguientes es la mejor actitud terapéutica ?:', '[{"position": 1, "text": "Doble derivación bilio-digestiva."}, {"position": 2, "text": "Intervención de Whipple."}, {"position": 3, "text": "Intervención de Puestow."}, {"position": 4, "text": "Coledocoduodenostomía."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-135', 'ddd691b233ae0d63f2ca538ae8c59c95ef08c23f', 2024, 0, 135, false, false, 'Aparato Digestivo', NULL, 'Hombre de 57 años con cirrosis hepática metabólica que consulta por un cuadro recidivante de confusión y desorientación a pesar del tratamiento con rifaximina y lactulosa. En la angio-CT se aprecia una comunicación portosistémica de gran calibre. La función hepática está alterada con MELD 17p y Child- Pugh B8. ¿ Cuál de los siguientes tratamientos es más apropiado ?:', '[{"position": 1, "text": "Trasplante hepático."}, {"position": 2, "text": "Oclusión de la comunicación portosistémica."}, {"position": 3, "text": "Colocación de TIPS (protesis intrahepática percutánea transyugular)."}, {"position": 4, "text": "Trasplante de microbiota fecal."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-136', 'a30675264441ddcbd09766635971097ae2bbdb01', 2024, 0, 136, false, false, 'Aparato Digestivo', NULL, 'Hombre de 45 años que presenta un pólipo sesil de aspecto macroscópicamente benigno en colon sigmoide. Extraído mediante polipectomía endoscópica, la biopsia muestra un adenocarcinoma. ¿ Cuál de los siguientes hallazgos anatomopatológicos indica alto riesgo de recurrencia y es indicación de colectomía segmentaria ?:', '[{"position": 1, "text": "Tumor T1 con invasión de la submucosa sm3."}, {"position": 2, "text": "Distancia al borde de sección de 2,5 mm."}, {"position": 3, "text": "Tumor bien diferenciado. 3. Tomografía axial sin y con contraste IV."}, {"position": 4, "text": "Ausencia de invasión linfovascular."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-137', '23f18f81973feba31da0526e9524b00106be8bb4', 2024, 0, 137, false, false, 'Aparato Digestivo', NULL, 'Mujer de 65 años que consulta por la aparición repentina de dolor en la parte superior del abdomen y naúseas recurrentes con escasos vómitos. Se intenta colocar una sonda nasogástrica y no se consigue progresar al estómago. Esta tríada es característica de la presentación clínica de:', '[{"position": 1, "text": "Síndrome de Mallory-Weiss."}, {"position": 2, "text": "Bezoar gástrico."}, {"position": 3, "text": "Vólvulo gástrico agudo."}, {"position": 4, "text": "Oclusión intestinal alta."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-138', '25a1d6df0d1218af3e06f31cff3dd92bd2d3e709', 2024, 0, 138, false, false, 'Aparato Digestivo', NULL, '¿Cuál de los siguientes genes puede estar afectado en familias que desarrollan tumores malignos de colon en sucesivas generaciones ?:', '[{"position": 1, "text": "RAS."}, {"position": 2, "text": "p53."}, {"position": 3, "text": "BRCA1."}, {"position": 4, "text": "MLH1."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-139', '88048414b17a4744da1f904908a8e547d33af6c7', 2024, 0, 139, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 50 años que consulta por presentar una tumoración reductible en región inguinal que se aprecia tras maniobras de Valsalva y que apareció tras realizar un esfuerzo 1 mes antes. En relación con la patología más probable, indique la opción terapéutica adecuada:', '[{"position": 1, "text": "Resección de la tumoración para análisis anatomopatológico."}, {"position": 2, "text": "Colocación de una prótesis mediante un abordaje endovascular."}, {"position": 3, "text": "Realización de una derivación o bypass a nivel de la lesión."}, {"position": 4, "text": "Reparación del defecto herniario con una prótesis para evitar tensión."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-140', 'e192a633fa7cc26cca00d88b63ad50d3f52e48f4', 2024, 0, 140, false, false, 'Miscelánea', NULL, 'En relación con la clasificación de las heridas quirúrgicas de los Centers for Disease Control and Prevention, una incisión en la que se encuentra inflamación aguda no purulenta es:', '[{"position": 1, "text": "Grado I: Herida limpia."}, {"position": 2, "text": "Grado II: Herida limpia contaminada."}, {"position": 3, "text": "Grado III: Herida contaminada."}, {"position": 4, "text": "Grado IV: Herida sucia-infectada."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-141', '1ae8cf6455512a3d7c0806d1e0c871f647ff5972', 2024, 0, 141, false, false, 'Urología', NULL, 'Varón de 66 años sin antecedentes de interés que acude a urgencias por dolor tipo cólico en fosa renal derecha, sin repercusión analítica. El dolor se controla con el tratamiento analgésico pautado. La ecografía abdominal describe la existencia de un engrosamiento focal de 2,5 cm de diámetro en pelvis renal derecha. ¿ Qué prueba se debe solicitar para completar el estudio ?:', '[{"position": 1, "text": "Resonancia magnética."}, {"position": 2, "text": "Urografía intravenosa."}, {"position": 4, "text": "Repetir la ecografía abdominal."}]'::jsonb, 3, NULL, 'definitiva', NULL, false, NULL, true, 'numeracion de opciones incompleta en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-142', '98a3e98a70435c31445646d176992d492ec95cf5', 2024, 0, 142, false, false, 'Nefrología', NULL, 'Hombre de 28 años con diagnóstico reciente de linfoma de Hodgkin, que consulta por debilidad y edematización progresivas. La exploración es normal salvo por la presencia de edema con fóvea hasta las rodillas. Análisis: urea 58 mg/dl, creatinina 0,78 mg/dl, sodio 138 mEq/l, potasio 4,3 mEq/l, albúmina 2 g/dl. Sistemático de orina: proteinuria 4+ (> 600 mg/dl) sin hematuria ni leucocituria. ¿ Cuál de las siguientes enfermedades es más probable que tenga ?:', '[{"position": 1, "text": "Glomerulonefritis de cambios mínimos."}, {"position": 2, "text": "Glomerulonefritis membranosa."}, {"position": 3, "text": "Glomerulonefritis membranoproliferativa."}, {"position": 4, "text": "Glomeroesclerosis focal y segmentaria."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-143', 'dee466c1c2e22a0ff5549c10482cbfabde5f39cb', 2024, 0, 143, false, false, 'Urología', NULL, 'Hombre de 17 años que acude a urgencias por dolor testicular izquierdo de 10 horas de evolución de inicio súbito, que le ha despertado mientras dormía, asociado a cortejo vegetativo y náuseas. En las últimas 24 horas refiere haber realizado actividad deportiva (un partido de fútbol en el que no recuerda haber sufrido traumatismo) y actividad sexual (con su pareja habitual y con preservativo). A la exploración hemiescroto izquierdo hipersensible, con testículo y epidídimo tumefactos y muy dolorosos, horizontalizados y discretamente aumentados de tamaño respecto al contralateral, signo Prehn negativo, transiluminación negativa. No hay disponible urólogo ni radiólogo de presencia física. ¿ Cuál es la actitud más apropiada ?:', '[{"position": 1, "text": "Intento de detorsión testicular manual en rotación externa y exploración quirúrgica en las primeras 24 horas."}, {"position": 2, "text": "Toma de constantes, analítica urgente (hemograma, bioquímica y sistemático de orina), analgesia y antibioticoterapia intravenosa."}, {"position": 3, "text": "Remitir a la consulta de urología de forma preferente."}, {"position": 4, "text": "Hielo local y analgesia intravenosa con reevaluación posterior."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-144', 'd00788dd9d8e55e35e4a0ac6e5aa07ceca2ce58d', 2024, 0, 144, false, false, 'Hematología', NULL, 'Hombre de 52 años que acude a urgencias por debilidad y dificultad para la articulación de la palabra. Constantes: TA 115/60 mmHg, FC 80 Ipm, temperatura 37,8℃. Exploración neurológica: bradilalia, bradipsiquia y pérdida de fuerza en mano izquierda. Auscultación y abdomen sin hallazgos. Petequias en cara interna de muslos y dorso de los pies. AngioTC cerebral sin signos de sangrado intracraneal ni patología isquémica aguda. Analítica: Hb 7,2 g/dl, 12.340 leucocitos (92 % PMN), plaquetas 14.600, urea 183 mg/dl, creatinina 2,3 mg/dl, bilirrubina total 2 mg/dl, transaminasas normales, LDH 2.125 UI, ferritina 1.582 ng/ml, haptoglobina < 30 mg/dl. Frotis de sangre periférica con anisocitosis y abundantes microesferocitos y esquistocitos (3-4 por campo) sin agregados plaquetarios. ¿ Cuál de los siguentes tratamientos es MENOS apropiado ?:', '[{"position": 1, "text": "Iniciar plasmaféresis con plasma fresco congelado de forma precoz."}, {"position": 2, "text": "Realizar transfusión de hematíes."}, {"position": 3, "text": "Realizar transfusión de plaquetas."}, {"position": 4, "text": "Iniciar tratamiento con corticoides."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-145', '249112768c7c36ab7eac2eb347e25112fc8e98e9', 2024, 0, 145, false, false, 'Nefrología', NULL, 'Mujer de 52 años que consulta por un rash eritematoso pruriginoso. Como antecedentes destacables consta un cólico nefrítico una semana antes, para el que recibió tratamiento con dexketoprofeno y omeprazol. En la analítica destaca un filtrado glomerular estimado de 45 ml/min (previamente normal), sin proteinuria ni otras alteraciones. ¿ Cuál de los siguientes diagnósticos es más probable y qué actitud terapéutica debe adoptarse ?:', '[{"position": 1, "text": "Toxicidad renal directa del dexketoprofeno y/o omeprazol. Con la suspensión de los fármacos sería suficiente."}, {"position": 2, "text": "Obstrucción de tracto urinario superior por litiasis. Realizar una ecografía para confirmarlo y, de ser así, eliminar la obstrucción."}, {"position": 3, "text": "Necrosis tubular aguda. Dar un margen de tiempo para la recuperación espontánea de las células tubulares."}, {"position": 4, "text": "Nefritis intersticial. Hacer una biopsia renal para confirmarlo y, en caso afirmativo, administrar corticoides."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-146', '6999bf9bafaa24196d8bdaee796e09fee388f8e1', 2024, 0, 146, false, false, 'Nefrología', NULL, '¿Cuál de las siguientes es causa de acidosis metabólica con brecha aniónica (anion gap) normal ?:', '[{"position": 1, "text": "Acidosis láctica por metformina."}, {"position": 2, "text": "Diarrea aguda."}, {"position": 3, "text": "Cetoacidosis diabética."}, {"position": 4, "text": "Intoxicación por metanol."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-147', '16867d1458204710deb7b88cff03f74705734649', 2024, 0, 147, false, false, 'Urología', NULL, 'En relación con el cáncer de próstata, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El principal factor de riesgo es la edad."}, {"position": 2, "text": "Los portadores del gen BRCA-1 tienen mayor predisposición a sufrir la enfermedad."}, {"position": 3, "text": "Es más frecuente en varones caucásicos."}, {"position": 4, "text": "Las grasas animales, la obesidad, el hábito tabáquico y el cadmio también se han relacionado con su etiopatogenia."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-148', '0577754b07c9ff03f84b31fb02bc2118bc6946a5', 2024, 0, 148, false, false, 'Endocrinología', NULL, 'Acude a consulta un paciente con diabetes mellitus tipo 2 de siete años de evolución, con un filtrado glomerular estimado de 35 ml/min. ¿ Cuál de los siguientes hallazgos NO apoya el diagnóstico de enfermedad renal diabética ?:', '[{"position": 1, "text": "Aumento lento de las cifras de creatinina sérica."}, {"position": 2, "text": "Presencia de retinopatía diabética."}, {"position": 3, "text": "Hematuria persistente (micro o macroscópica)."}, {"position": 4, "text": "Cociente albúmina/creatinina en orina > 30 mg/g."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-149', 'dec3cd6a23c8dc58330bfedb9049b578f41464d6', 2024, 0, 149, false, false, 'Hematología', NULL, 'Con respecto a la PET-TC con 18F- fluorodesoxiglucosa (18F-FDG) en pacientes con linfoma, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "Es más exacta para la valoración de la médula ósea en el linfoma de Hodgkin (LH)."}, {"position": 2, "text": "Realizada a mitad de tratamiento en el LH ayuda a decidir la duración del mismo."}, {"position": 3, "text": "Es útil en los linfomas no Hodgkin de bajo grado."}, {"position": 4, "text": "Al final del tratamiento puede diferenciar entre enfermedad residual y enfermedad activa."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-150', '70e3d91270e44ca49df4b4ccb5613e12dcff5068', 2024, 0, 150, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer de 21 años sin antecedentes de interés que consulta por palpitaciones, nerviosismo y cambios de comportamiento. Se le diagnostica de crisis de ansiedad. Diez días más tarde consulta de nuevo por cefalea, alucinaciones auditivas, discurso incoherente y síntomas psicóticos. La analítica general, la radiografía de tórax, la TC craneal y los estudios microbiológicos son normales. La resonancia magnética cerebral muestra hiperintensidad en FLAIR en hipocampo. En sangre se detectan anticuerpos contra receptores de N-metil-d-aspartato. ¿ Cuál de los siguientes diagnósticos es el más probable ?:', '[{"position": 1, "text": "Teratoma ovárico."}, {"position": 2, "text": "Sarcoma de Ewing."}, {"position": 3, "text": "Cáncer de mama."}, {"position": 4, "text": "Linfoma de Hodgkin."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2024-v0-151', 'b9c2d9d6f0b0be9026ac7c6d4a4c0d54f5f1f904', 2024, 0, 151, false, false, 'Bioestadística', NULL, '¿Cuál de los siguientes datos NO es relevante antes de iniciar un tratamiento adyuvante con fluorouracilo a un paciente intervenido de cáncer de colon ?:', '[{"position": 1, "text": "El aclaramiento de creatinina."}, {"position": 2, "text": "Determinación de la dihidropirimidina deshidrogenasa (DPD)."}, {"position": 3, "text": "Síntomas previos de neurotoxicidad."}, {"position": 4, "text": "Antecedentes de cardiopatía isquémica."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-152', '4d41864d21af4ef231473aa9e4127715dcc91c04', 2024, 0, 152, false, false, 'Hematología', NULL, 'En una anemia por deficiencia de hierro en una mujer joven por sangrado menstrual excesivo, sin otras complicaciones añadidas, ¿cuál de los siguientes parámetros analíticos estará aumentado ?:', '[{"position": 1, "text": "Concentración de ferritina en suero."}, {"position": 2, "text": "Concentración de hemoglobina en reticulocitos."}, {"position": 3, "text": "Volumen corpuscular medio de los hematíes. 3. Capacidad intrínseca."}, {"position": 4, "text": "Concentración de transferrina en suero."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-153', '9cfb28e380544431d4ced965942bc7df5d29f816', 2024, 0, 153, false, false, 'Hematología', NULL, 'Paciente de 62 años en estudio por una pancitopenia. Se realiza una punción de la medula ósea objetivando un 15 % de blastos mieloides con estudio citogenético normal. Según la clasificación de enfermedades de la OMS el proceso debería ser catalogado como:', '[{"position": 1, "text": "Leucemia mieloide aguda."}, {"position": 2, "text": "Síndrome mielodisplásico con exceso de blastos."}, {"position": 3, "text": "Anemia megaloblastica."}, {"position": 4, "text": "Aplasia medular."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-154', '65e7e43a920a08300911797908079d08ddcdf64d', 2024, 0, 154, false, false, 'Neumología y Cirugía Torácica', NULL, '¿Cuál de las siguientes alteraciones es más frecuente en el cáncer de pulmón no microcítico metastásico ?:', '[{"position": 1, "text": "Mutación de KRAS."}, {"position": 2, "text": "Mutación de BRAF."}, {"position": 3, "text": "Reordenamiento de ALK."}, {"position": 4, "text": "Fusión de NTRK."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-155', 'b86603f8093ff2fc3efce10a472c01f5d6202b91', 2024, 0, 155, false, false, 'Hematología', NULL, 'Un paciente con grupo sanguíneo A positivo y una leucemia mieloide aguda es sometido a un trasplante hematopoyético con un donante B positivo. La médula del donante prende adecuadamente alcanzando un quimerismo completo. Sin haber recibido transfusiones en los cuatro meses previos, a los seis meses del procedimiento, permaneciendo en quimerismo completo, se realiza un nuevo grupo sanguíneo al receptor. El resultado será:', '[{"position": 1, "text": "A positivo. El grupo sanguíneo permanece inalterable durante toda la vida."}, {"position": 2, "text": "AB positivo. Existe una mezcla de ambos grupos en los hematíes."}, {"position": 3, "text": "B positivo. Ha cambiado de grupo adquiriendo el del donante."}, {"position": 4, "text": "O positivo. Los anticuerpos anti-transferasa del receptor inhiben la expresión de los grupos sanguíneos, siendo todos los pacientes trasplantados del grupo O."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-156', 'bb066a9af7b707941344307e9bbb4d7903f7296e', 2024, 0, 156, false, false, 'Ginecología y Obstetricia', NULL, 'En relación con la indicación de irradiación parcial del cáncer de mama, señale la respuesta correcta:', '[{"position": 1, "text": "No está indicada en pacientes postmenopáusicas."}, {"position": 2, "text": "Solo la pueden recibir pacientes diagnosticadas de carcinoma in situ."}, {"position": 3, "text": "Es de elección en pacientes con ganglios positivos."}, {"position": 4, "text": "No se debe emplear cuando hay más de un foco tumoral o lesiones multicéntricas."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-157', '91b50b56d35d146bd27f60b34423608a1d8d79ad', 2024, 0, 157, false, false, 'Miscelánea', NULL, 'El conjunto de todas las capacidades físicas y mentales de una persona que permiten hacer frente a los cambios del entorno, originando discapacidad cuando fallan, se denomina:', '[{"position": 1, "text": "Fragilidad."}, {"position": 2, "text": "Morbilidad."}, {"position": 4, "text": "Discapacidad."}]'::jsonb, 3, NULL, 'definitiva', NULL, false, NULL, true, 'numeracion de opciones incompleta en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-158', 'b25d1a4fda8c6121f00ee2f686fdb0c3987bcac5', 2024, 0, 158, false, false, 'Genética e Inmunología', NULL, 'Respecto a los cambios del sistema inmunitario que aparecen con el envejecimiento, definidos como inmunosenescencia, señale la respuesta correcta:', '[{"position": 1, "text": "La disminución de interleuquina 6 se relaciona con fragilidad y demencia."}, {"position": 2, "text": "Disminuye el número de linfocitos T."}, {"position": 3, "text": "Disminuye el factor de necrosis tumoral."}, {"position": 4, "text": "Disminuye la producción de autoanticuerpos por los linfocitos B."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-159', '039844e12b8324b79694270f4b532dcce22705d7', 2024, 0, 159, false, false, 'Miscelánea', NULL, 'Una de las siguientes escalas, usadas para valorar la fragilidad, requiere la realización de pruebas de ejecución:', '[{"position": 1, "text": "La escala FRAIL."}, {"position": 2, "text": "El índice de fragilidad de Rockwood."}, {"position": 3, "text": "La Clinical Frailty Scale (CFS)."}, {"position": 4, "text": "La Short Physical Performance Battery (SPPB)."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-160', 'de7f3cd25a7e2d85b709e4973e7bf272cf46e0b6', 2024, 0, 160, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 84 años que acude a su médico de familia porque, tras haberse caído tres veces a lo largo del último año, tiene miedo a volver a caerse. Se le hace una prueba cronometrada "Levántese y Ande" (Get Up and Go), que tarda en completar 21 segundos (normal <10 s). Respecto el riesgo de caída que presenta, señale la respuesta correcta:', '[{"position": 1, "text": "El riesgo es bajo, por lo que se reevaluará dentro de un año."}, {"position": 2, "text": "El riesgo es intermedio, por lo que se realizará educación general para prevenir futuras caídas sin intervención individualizada."}, {"position": 3, "text": "No tiene riesgo de nuevas caídas, no precisa seguimiento."}, {"position": 4, "text": "El riesgo es alto, por lo que se realizará una valoración multifactorial del riesgo de caídas con intervención individualizada."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-161', '6e0587a61907dddd3a4c068b923b4b2884b2cc3c', 2024, 0, 161, false, false, 'Endocrinología', NULL, 'Hombre de 91 años que consulta por creciente dificultad para hacer sus tareas habituales y sensación de debilidad. Su IMC es de 22,5 y su masa muscular medida por bioimpedanciometría es de 14 kg (normal >20 kg) con aumento del porcentaje de grasa, su fuerza de prensión es de 19 kg (>27 kg) y su velocidad de la marcha 0,7 m/s (>1,0 m/s). ¿ Cuál de los siguientes diagnósticos es más probable ?:', '[{"position": 1, "text": "Envejecimiento normal."}, {"position": 2, "text": "Sarcopenia grave."}, {"position": 3, "text": "Malnutrición moderada."}, {"position": 4, "text": "Caquexia."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-162', '5846f374ea2506d5514596074683a6ed80fe4bc3', 2024, 0, 162, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 93 años con antecedentes de HTA, diabetes mellitus, hiperplasia benigna de próstata y demencia mixta leve. Necesita ayuda de una persona para bajar las escaleras, es incontinente urinario pero él mismo se cambia el pañal y es independiente para el resto de las actividades básicas de la vida diaria, con dependencia para la mayoría de actividades instrumentales. Ha sido intervenido de una fractura subcapital de fémur derecho Garden IV de etiología osteoporótica con colocación de hemiartroplastia, sin presentar complicaciones médicas ni quirúrgicas. Señale la respuesta correcta:', '[{"position": 1, "text": "No es candidato a tratamiento osteoprotector por edad y presencia de demencia."}, {"position": 2, "text": "No se deben iniciar bifosfonatos si presenta hipocalcemia."}, {"position": 3, "text": "Debe suplementarse con calcio aunque sus valores sean normales."}, {"position": 4, "text": "Debe permanecer encamado seis semanas tras la intervención quirúrgica para mejorar la consolidación de la fractura."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-163', 'bb21a421851383abc1be5f1e09cba8aa145e401a', 2024, 0, 163, false, false, 'Endocrinología', NULL, 'La técnica quirúrgica indicada en los pacientes con adenoma tiroideo tóxico solitario que precisan intervención quirúrgica es:', '[{"position": 1, "text": "Nodulectomía."}, {"position": 2, "text": "Hemitiroidectomía del lado afecto."}, {"position": 3, "text": "Tiroidectomía subtotal."}, {"position": 4, "text": "Tiroidectomía total."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-164', '619422efadb14d36b230d30130e109a03b6d7aff', 2024, 0, 164, false, false, 'Endocrinología', NULL, 'Señale la respuesta correcta en relación con el tratamiento con yodo radiactivo en los pacientes con cáncer diferenciado de tiroides:', '[{"position": 1, "text": "Se debe administrar antes de la tiroidectomía para disminuir el tamaño tumoral."}, {"position": 2, "text": "Administrado con carácter ablativo post- tiroidectomía facilita el seguimiento con la determinación de tiroglobulina sérica."}, {"position": 3, "text": "Está indicado únicamente cuando existen metástasis a distancia."}, {"position": 4, "text": "En pacientes de bajo riesgo o muy bajo riesgo reduce las recurrencias y prolonga la supervivencia."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-165', '85098bf32c5acdc449167f2b41d2bc9fa907ac98', 2024, 0, 165, false, false, 'Endocrinología', NULL, 'Si usted está de guardia y le avisan por un paciente con malestar general, cefalea y náuseas, en quien encuentra una hiponatremia con función renal normal ¿qué esperaría encontrar si la causa de la misma fuera un SIADH ?:', '[{"position": 1, "text": "Osmolalidad plasmática >270 mosm/Kg."}, {"position": 2, "text": "Hipovolemia."}, {"position": 3, "text": "Osmolalidad urinaria >100 moms/Kg."}, {"position": 4, "text": "Excreción urinaria de socio reducida con ingesta adecuada de sal y agua."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-166', '42eabbe22b8ddad91c1803c3e6a14bcd73665755', 2024, 0, 166, false, false, 'Endocrinología', NULL, 'Mujer de 25 años, obesa, que consulta por clínica de 2 meses de evolución de pérdida de 5 Kg de peso, palpitaciones, dificultad para el sueño nocturno y nerviosismo. A la exploración física destaca temblor fino distal, frecuencia cardiaca de 110 lpm y no presenta bocio. Se realiza analítica que muestra TSH suprimida, T4 elevada y tiroglobulina baja. La gammagrafía tiroidea muestra una absorción disminuida de yodo radiactivo. ¿ Cuál de los siguientes le parece el diagnóstico más probable?', '[{"position": 1, "text": "Tirotoxicosis facticia."}, {"position": 2, "text": "Tiroiditis subaguda."}, {"position": 3, "text": "Hipertiroidismo por enfermedad de Graves."}, {"position": 4, "text": "Teratoma de ovario (estruma ovárico)."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-167', '29db497c77260360c0118424942000fcb422e88f', 2024, 0, 167, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre que consulta por la aparición de linfadenopatías generalizadas no dolorosas y lesiones cutáneas maculosas, papulosas, papuloescamosas y pustulosas. Las máculas son de color rojo pálido o rosa, no pruriginosas, distribuidas por tronco, zonas proximales de extremidades y en palmas y plantas, coexisten en distintas fases de evolución. Refiere, además, malestar general, febrícula, odinofagia y cefalea. En los antecedentes personales figuran que fue diagnosticado de infección por VIH y abandonó el tratamiento. Reconoce que practica con frecuencia sexo con otros hombres. ¿ Cuál de las siguientes respuestas es INCORRECTA en relación con la enfermedad que sospecha que padece ?:', '[{"position": 1, "text": "Puede cursar con uveítis y producir ceguera."}, {"position": 2, "text": "Las lesiones cutáneas involucionan espontáneamente entre 1 y 6 meses."}, {"position": 3, "text": "Una cifra baja de linfocitos CD4+ (<350 cel/microL) es un riesgo para desarrollar afectación del sistema nervioso central y puede estar indicado practicar una punción lumbar."}, {"position": 4, "text": "La azitromicina es una buena opción para el tratamiento de la enfermedad, ya que la resistencia a los macrólidos es escasa."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-168', '4ffb4a306b29c0a1e1db5a838ca9b9fd25fcee4c', 2024, 0, 168, false, false, 'Enfermedades Infecciosas', NULL, 'El tratamiento de la leishmaniasis visceral en personas con infección por VIH con inmunodeficiencia grave se basa en el uso de:', '[{"position": 1, "text": "Anfotericina B liposomal."}, {"position": 2, "text": "Voriconazol y anfotericina B liposomal."}, {"position": 3, "text": "Anfotericina B liposomal y miltefosina."}, {"position": 4, "text": "Miltefosina y paromomicina."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-169', '0e33f10e68e266c3c007fefc7ec6bf0141bac195', 2024, 0, 169, false, false, 'Ginecología y Obstetricia', NULL, 'En una paciente joven sin antecedentes de interés que después de un tratamiento antibiótico por otro motivo es diagnosticada de candidiasis vaginal, es cierto que:', '[{"position": 1, "text": "El tratamiento de elección es un comprimido vaginal de 500 mg de clotrimazol en dosis única."}, {"position": 2, "text": "Si estuviera embarazada, el tratamiento antifúngico debería ser oral."}, {"position": 3, "text": "Es preciso tratar a su pareja sexual, aunque esté asintomática."}, {"position": 4, "text": "Es necesario realizar un cribado de otras enfermedades de transmisión sexual."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-170', 'dd32ff7577eb48a3038c699abdceb46f4f810e8c', 2024, 0, 170, false, false, 'Enfermedades Infecciosas', NULL, 'Sobre el tratamiento con antivíricos orales en un paciente con herpes zoster de menos de 72 horas de evolución, es cierto que:', '[{"position": 1, "text": "Deja de ser contagioso a las 24 horas de inicio del tratamiento."}, {"position": 2, "text": "Deben tratarse los síntomas con analgésicos además del tratamiento del herpes."}, {"position": 3, "text": "En casos con muy pocas lesiones, su efectividad es similar al tratamiento tópico con antivíricos."}, {"position": 4, "text": "Sólo está indicado en pacientes inmunodeprimidos."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-171', 'fdb153d743cb6dc6224b118896f3a45162370f58', 2024, 0, 171, false, false, 'Enfermedades Infecciosas', NULL, 'En la revisión de un hombre de 27 años que ha comenzado tratamiento con tenofovir/emtricitabina como profilaxis preexposición al VIH (PrEP) hace tres meses, se identifica una serología positiva a VIH. En el momento del inicio de la PrEP la serología a VIH era negativa y la adherencia al tratamiento ha sido completa. La explicación más probable para el fracaso de la PrEP en este caso es:', '[{"position": 1, "text": "Resistencias primarias a los antirretrovirales usados."}, {"position": 2, "text": "Haber iniciado la PrEP en el periodo ventana de la infección por VIH."}, {"position": 3, "text": "Se trata de un falso positivo."}, {"position": 4, "text": "Mayor susceptibilidad al VIH por las frecuentes infecciones de transmisión sexual asociadas a la PrEP."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-172', '60dd922338415ca00fcf6719ea9ed2c02e9efc10', 2024, 0, 172, false, false, 'Dermatología', NULL, 'Ante un caso de sarna en un paciente inmunocompetente, señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El tratamiento de elección es permetrina tópica al 5 % desde la línea mandibular hasta los dedos de los pies, dejando actuar entre 8 y 14 horas."}, {"position": 2, "text": "Es preciso lavar la ropa usada en las 48 horas previas y otras ropas del hogar al menos a 50 grados, lavado en seco o en su defecto poner la ropa en bolsas de plástico durante 15 días, para eliminar el parásito correctamente."}, {"position": 3, "text": "La medida del efecto terapéutico del tratamiento es a través de la desaparición del picor en las primeras 48 horas."}, {"position": 4, "text": "En caso de fracaso del tratamiento tópico o sarna nodular, el tratamiento de elección en nuestro entorno es la ivermectina oral en dosis única."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-173', '06202c2471f99ddb4ac0373bd45dee1060cccb68', 2024, 0, 173, false, false, 'Hematología', NULL, 'Mujer de 45 años con antecedentes de colitis ulcerosa, que consulta por fiebre diaria de hasta 40℃ acompañada de escalofríos, astenia, anorexia y cefalea intensa. En la exploración está febril, normotensa, a 90 lpm
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2024-v0-201', '216df3220b32de742c3125b1520398f4cce6bd85', 2024, 0, 201, true, false, 'Endocrinología', NULL, '¿Cuál de las siguientes NO es una respuesta hormonal a la hipoglucemia ?:', '[{"position": 1, "text": "Aumento de la secreción de hormona del crecimiento."}, {"position": 2, "text": "Reducción de la secreción de glucagón."}, {"position": 3, "text": "Aumento de la secreción de cortisol."}, {"position": 4, "text": "Aumento de la secreción de adrenalina."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-202', 'f324e7179da47b1c34a410549759f137f1792448', 2024, 0, 202, true, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Tras el diagnóstico en urgencias de embolismo pulmonar, es necesario hacer una valoración y estratificación del riesgo para decidir cual es la mejor opción terapéutica. Indique cual de los siguientes es un factor de alto riesgo de tener un resultado clínico adverso:', '[{"position": 1, "text": "Extensión del embolismo pulmonar con función normal del ventrículo derecho y normotensión."}, {"position": 2, "text": "Identificación en la TC torácica de signos de crecimiento del ventriculo izquierdo."}, {"position": 3, "text": "Valor elevado del dímero D."}, {"position": 4, "text": "Signos de disfunción del ventrículo derecho en el ecocardiograma con presión arterial sistólica <90 mmHg mantenida."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-203', '5e8c3fe477ccef99b936cfcf1d94602577d1f501', 2024, 0, 203, true, false, 'Aparato Digestivo', NULL, 'En un paciente con cáncer de colon metastásico ¿cuál de las siguientes determinaciones moleculares se deben realizar antes de comenzar el tratamiento sistémico ?:', '[{"position": 1, "text": "EGFR, NRAS, KRAS, proteínas reparadoras, HER2."}, {"position": 2, "text": "NRAS, KRAS, BRAF, proteínas reparadoras."}, {"position": 3, "text": "EGFR, NRAS, KRAS, BRAF, proteínas reparadoras."}, {"position": 4, "text": "NRAS, KRAS, BRAF, proteínas reparadoras, PI3K."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-204', '781f708759ccb377be275b4c73e96e309d587bda', 2024, 0, 204, true, false, 'Reumatología', NULL, 'Hombre de 45 años que en las últimas 6 semanas presenta astenia, pérdida de 5 kg de peso y artromialgias de predominio en región proximal de ambas extremidades inferiores, junto a hipoestesia asimétrica en manos y pies. Además, en los últimos 3 días desarrolla una livedo reticularis y varios nódulos subcutáneos, eritematosos y dolorosos, en cara anterior de ambas piernas. En la analítica destaca VSG 90 mm/h (normal <20) y proteína C reactiva 12 mg/dl (normal < 1,0). Radiografía de tórax normal. Electroneuromiografia (ENMG): hallazgos compatibles con mononeuritis múltiple. Teniendo en cuenta el diagnóstico más probable, marque la opción correcta:', '[{"position": 1, "text": "A diferencia de lo objetivado en el paciente, la alteración de la ENMG más característica es una neuropatía de fibra fina."}, {"position": 2, "text": "Una biopsia de músculo no permitiría demostrar histológicamente la enfermedad."}, {"position": 3, "text": "A pesar de la sospecha diagnóstica, no cumple criterios clasificatorios de la enfermedad, por lo que no es posible diagnosticarle."}, {"position": 4, "text": "Existen pacientes que cumplen los criterios clasificatorios de la enfermedad que presentan mutaciones con pérdida de función en el gen CECR1 que codifica la adenosina desaminasa 2."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-205', '956284f552c763e31f246ff1b38b2b1d1316b2f8', 2024, 0, 205, true, false, 'Dermatología', NULL, 'Paciente de 26 años sin antecedentes de interés que consulta por engrosamiento y cambio de color de la parte distal de la uña del dedo gordo del pie derecho. A la exploración se observa una muy probable onicomicosis de la uña, sin otras lesiones o uñas afectadas. Sobre esta situación clínica es cierto que:', '[{"position": 1, "text": "El tratamiento con amorolfina tópica al 5 % dos veces por semana por un periodo de 3 meses suele ser efectivo."}, {"position": 2, "text": "Si la lesión afectara la matriz ungueal el tratamiento debe prolongarse hasta los 6-9 meses."}, {"position": 3, "text": "El tratamiento oral de elección en este caso es la griseofulvina."}, {"position": 4, "text": "En casos de resistencia una opción es el tratamiento con itraconazol oral 200 mg cada 24 horas durante 12 semanas."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-206', '06d3f5a83f59d46d1232c43d6a18e988ef039954', 2024, 0, 206, true, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Mujer de 49 años diagnosticada de dislipemia. Exfumadora hace 3 años y no consume alcohol. Exploración física: presión arterial 129/81 mmHg, electrocardiograma, retinografía y exploración de pies normales. Índice de masa corporal 28 kg/m2. Analítica: glucemia en ayunas 103 mg/dl, colesterol total 183 mg/dl, colesterol LDL 104 mg/dl, colesterol HDL 42 mg/dl, triglicéridos 186 mg/dl. Filtrado glomerular estimado (CKD-EPI) 55 ml/min/1,7 2m2, cociente albúmina/creatinina en orina 4 mg/g. ¿ Qué riesgo cardiovascular presenta según las guías europeas de prevención cardiovascular ?:', '[{"position": 1, "text": "Riesgo bajo."}, {"position": 2, "text": "Riesgo moderado."}, {"position": 3, "text": "Riesgo alto."}, {"position": 4, "text": "Riesgo muy alto."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-207', '4c3c633979dbe8decd2d9968e17b92c38fda8c98', 2024, 0, 207, true, false, 'Endocrinología', NULL, 'Mujer de 67 años exfumadora con antecedentes de hipertensión arterial, diabetes mellitus tipo 2 de 10 años de evolución con microalbuminuria y obesidad es enviada a su consulta. Aporta un análisis con una hemogloblina glicada de 10 %, colesterol total de 210 mg/dl, colesterol LDL no calculable, colesterol HDL de 30 mg/dl y unos triglicéridos de 496 mg/dL. Función renal normal. Respecto a la hipertrigliceridemia, señale la respuesta correcta:', '[{"position": 1, "text": "El primer escalón es conseguir un control adecuado de su diabetes para corregir la hipertrigliceridemia y añadir una estatina."}, {"position": 2, "text": "Aunque el control de la diabetes es necesario, no influye en la hipertrigliceridemia. El primer escalón es añadir ácidos grasos omega-3."}, {"position": 3, "text": "La primera opción de tratamiento es combinar gemfibrozilo con una estatina."}, {"position": 4, "text": "La primera opción es iniciar tratamiento con fibratos."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-208', 'ce80fec2e254ee15c67833e9e198bdc4cd24c40b', 2024, 0, 208, true, false, 'Miscelánea', NULL, 'Con respecto a la retirada de medios de soporte vital en casos de futilidad de los tratamientos en un paciente en situación terminal ¿cuál de las siguientes afirmaciones es cierta ?:', '[{"position": 1, "text": "Es aceptable éticamente, aunque con ello sobrevenga la muerte del paciente."}, {"position": 2, "text": "Se trata de una medida que depende fundamentalmente de la voluntad del médico responsable del paciente."}, {"position": 3, "text": "Es una práctica equivocada y obsoleta desde que existen medios sofisticados de soporte vital artificial."}, {"position": 4, "text": "Según la ley española es eutanasia."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-209', '8723b42e70b3191343437ae77c93691824ec61c4', 2024, 0, 209, true, false, 'Miscelánea', NULL, 'La vía subcutánea es de gran utilidad en el tratamiento de pacientes en situación de cuidados paliativos y se considera de elección cuando la vía oral no es posible. Sin embargo, hay fármacos cuyo uso por vía subcutánea está desconsejado. Uno de esos fármacos es:', '[{"position": 1, "text": "Furosemida."}, {"position": 2, "text": "Metamizol."}, {"position": 3, "text": "Haloperidol."}, {"position": 4, "text": "Metoclopramida."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2024-v0-210', 'b9573df724caf64348ab514a76f3e876a187eedf', 2024, 0, 210, true, false, 'Enfermedades Infecciosas', NULL, 'El certificado médico de defunción (CMD) es un documento de carácter jurídico-administrativo necesario para obtener la licencia de enterramiento del cuerpo de una persona fallecida. Si existe una sospecha razonable de que la persona ha fallecido como consecuencia de una neumonía provocada por una infección por COVID-19 ¿cuál de las siguientes afirmaciones es cierta ?:', '[{"position": 1, "text": "En el CMD se hará constar que el cadáver pertenece al grupo I, por presentar enfermedad infecciosa que supone un riesgo relevante para la salud pública."}, {"position": 2, "text": "No se puede cumplimentar el CMD por tratarse de muerte sospechosa de criminalidad."}, {"position": 3, "text": "No se puede cumplimentar el CMD por que sólo se dispone de criterios de presunción y no de confirmación, aunque las circunstancias del fallecimiento y la patobiografía sean compatibles."}, {"position": 4, "text": "Se hará constar la infección por COVID-19 en el apartado de causa fundamental y no en el apartado de causa inmediata."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-001', '9cd342a912ccc08a1368b9e20c695fc51f810fc7', 2025, 0, 1, false, false, 'Genética e Inmunología', NULL, 'Mujer de 42 años que acude a la consulta de genética por un diagnóstico reciente de cáncer de endometrio. En base a los antecedentes familiares que constan en la imagen, ¿cuál de los siguientes síndromes es más probable que presente?:', '[{"position": 1, "text": "Poliposis adenomatosa familiar."}, {"position": 2, "text": "Síndrome de Lynch."}, {"position": 3, "text": "Síndrome de cáncer de mama y ovario hereditario."}, {"position": 4, "text": "Síndrome de Cowden."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_1.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-002', 'd15a7bb3423ef27169b833123e8a16caeb7b1c9f', 2025, 0, 2, false, false, 'Oftalmología', NULL, 'Paciente de 65 años que acude a urgencias por disminución brusca de agudeza visual en ojo derecho. La retinografía de dicho ojo se muestra en la imagen. Uno de los siguientes tratamientos está indicado para una enfermedad que es un factor de riesgo para esta situación. Indique cuál:', '[{"position": 1, "text": "Latanoprost y timolol."}, {"position": 2, "text": "Flecainida."}, {"position": 3, "text": "Hidroxicloroquina."}, {"position": 4, "text": "Complejos vitamínicos y antioxidantes."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_2.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-003', 'a63fcf47c31d23d44c3c9acd4e2b37f386543082', 2025, 0, 3, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Hombre de 70 años exfumador de un paquete al día y bebedor de 2 copas de vino al día consulta por una molestia faríngea de 1 mes de evolución. Se observa exudado amigdalar por lo que se inicia tratamiento antibiótico. El resultado del test de estreptococo es negativo. La clínica persiste y se añade odinofagia con otalgia refleja y leve cambio en el timbre de la voz. Nota un bulto duro de unos 2 cm a nivel II cervical ipsilateral no doloroso. La orofaringoscopia se refleja en la imagen asociada (imagen aumentada en el recuadro resaltado en rojo), ¿Cuál es la sospecha diagnóstica y su manejo?:', '[{"position": 1, "text": "Resistencia bacteriana a antibioterapia recibida, precisa cultivo de exudado faríngeo con antibiograma para indicación adecuada."}, {"position": 2, "text": "Sospecha de absceso periamigdalino izquierdo, será remitido a urgencias de Otorrinolaringología para drenaje quirúrgico."}, {"position": 3, "text": "Sospecha de neoplasia maligna de amígdala palatina, será remitido preferente-urgente a Otorrinolaringología."}, {"position": 4, "text": "Sospecha de angina de Plaut-Vincent, remitido a Otorrinolaringología para realización de biopsia de ganglio para estudio de linfoma."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_3.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-004', '709c9ccb3e38b75fede0e43b9a0f6a3d6e520a76', 2025, 0, 4, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', NULL, 'Niña de 7 años que acude por otalgia y otorrea purulenta derecha desde hace 3 semanas, tratada con antibióticos y antiinflamatorios. Tras la resolución de las manifestaciones clínicas, vuelve a aparecer la otorrea por lo que se pauta de nuevo tratamiento antibiótico. A los 5 días se objetiva una tumefacción retroauricular. En la otoscopia se pone de manifiesto una leve retracción de la membrana timpánica, escasa secreción blanquecina en el conducto auditivo externo y una tumefacción retroauricular blanda que ocasiona un mínimo desplazamiento anterior del pabellón auricular. Indique el diagnóstico que sugiere la imagen de resonancia magnética mostrada:', '[{"position": 1, "text": "Absceso subperióstico extracraneal."}, {"position": 2, "text": "Trombosis venosa cerebral."}, {"position": 3, "text": "Absceso cerebral retromastoideo."}, {"position": 4, "text": "Área de cerebritis retromastoidea."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_4.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-005', '7a060067ec6c35d283cab1a8618a3001603b48ac', 2025, 0, 5, false, false, 'Ginecología y Obstetricia', NULL, 'Una mujer de 18 años acude a urgencias por dolor abdominal intenso, febrícula, test de embarazo positivo y manchado vaginal de 3 días de evolución junto con líquido libre intraabdominal en la ecografía. Se realiza una laparoscopia en la que se encuentra el siguiente hallazgo tras aspirar sangre de la cavidad abdominal. ¿Cuál es el diagnóstico más probable de los siguientes?:', '[{"position": 1, "text": "Gestación ectópica."}, {"position": 2, "text": "Quiste de ovario complicado."}, {"position": 3, "text": "Apendicitis aguda."}, {"position": 4, "text": "Enfermedad inflamatoria pélvica."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_5.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-006', 'f167abdc6d521fc3a55fb309e38a288d12eb20a5', 2025, 0, 6, false, false, 'Neurología y Neurocirugía', NULL, 'Hombre de 40 años que presenta cefalea brusca con exploración neurológica normal. Se realiza TC craneal que se muestra en la imagen y una angiografía cerebral en la que no se encuentra patología subyacente. El cuadro clínico más probable es:', '[{"position": 1, "text": "Hemorragia subaracnoidea traumática occipital."}, {"position": 2, "text": "Hemorragia causada por una malformación arteriovenosa angiográficamente oculta."}, {"position": 3, "text": "Hemorragia subraracnoidea perimesencefálica con un probable origen venoso o capilar."}, {"position": 4, "text": "Hemorragia causada por una discrasia sanguínea."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_6.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-007', '921c846259e9d7e9c1f32cc2fa5a04e734176f23', 2025, 0, 7, false, false, 'Neurología y Neurocirugía', NULL, 'Hombre de 75 años consulta por un cuadro de dificultad para la marcha de 2 años de evolución de forma progresiva. Presenta reflejos vivos en las cuatro extremidades. Se muestra la RM cervical realizada. Con respecto al cuadro clínico del paciente señale la respuesta INCORRECTA:', '[{"position": 1, "text": "El cuadro de paraparesia puede ser asimétrico."}, {"position": 2, "text": "La progresión de la enfermedad es lenta pero puede acelerarse por movimientos de flexión o extensión cervical forzados."}, {"position": 3, "text": "Se trata de una enfermedad primaria de motoneurona."}, {"position": 4, "text": "La incontinencia urinaria aparece con la progresión de la enfermedad."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_7.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-008', '63cba472d1c1e578456f930cad4bad66552e71d2', 2025, 0, 8, false, false, 'Rehabilitación', NULL, 'Mujer de 14 años derivada a Rehabilitación para el manejo de una deformidad de la columna vertebral. Tuvo la menarquía a los 10 años. En la exploración física se aprecia mínima asimetría de escápulas, el eje occipito-sacro está centrado y en el test de Adams se observa una gibosidad torácica derecha de 10 mm. Se aporta teletradiografía de columna en proyección antero-posterior. ¿Cuál de los siguientes considera el manejo más adecuado a seguir?:', '[{"position": 1, "text": "Observación, con recomendación específica de ejercicios y revisión posterior."}, {"position": 2, "text": "Corsé de Milwaukee a tiempo completo."}, {"position": 3, "text": "Corsé de Boston a tiempo parcial."}, {"position": 4, "text": "Derivación a cirugía para tratamiento quirúrgico."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_8.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-009', '434d7c9eec61b5b06f5e7ff0ee3e220dc36b9c37', 2025, 0, 9, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 60 años de edad que tras dolor brusco y chasquido en hombro presenta la siguiente deformidad en el brazo. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Rotura de la porción larga del bíceps braquial."}, {"position": 2, "text": "Rotura de la porción corta del bíceps braquial."}, {"position": 3, "text": "Rotura del tendón distal del bíceps braquial."}, {"position": 4, "text": "Rotura del tendón del pectoral mayor."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_9.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-010', '4da4045659f8e33532874f0ea0bd0db36d8ff77d', 2025, 0, 10, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Paciente de 41 años, de talla baja, consulta por dolor en ambas caderas, más intenso en la izquierda. Refiere haber tenido dolor en caderas a edades tempranas aunque nunca consultaron por este motivo. Tras estudio radiográfico de caderas, se decide prótesis total de cadera izquierda, siguiendo buena evolución. Durante el postoperatorio el paciente refiere además dolor en hombros. Ante la sospecha diagnóstica se solicita una teletradiografía (ver imagen). Indique qué proceso es más probable que padezca el paciente desde su infancia:', '[{"position": 1, "text": "Enfermedad de Perthes."}, {"position": 2, "text": "Osteonecrosis multifocal."}, {"position": 3, "text": "Epifisiolisis bilateral de cadera."}, {"position": 4, "text": "Displasia epifisaria múltiple."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_10.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-011', '094584481201c25d7867c2cd029779c99cccc789', 2025, 0, 11, false, false, 'Traumatología y Cirugía Ortopédica', NULL, 'Hombre de 40 años que consulta por tumoración dolorosa en cara interna de rodilla. En el estudio radiográfico se obtiene esta imagen. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Osteomielitis."}, {"position": 2, "text": "Osificación heterotópica."}, {"position": 3, "text": "Encondroma."}, {"position": 4, "text": "Osteocondroma."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_11.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-012', 'ce252fec32081d6825b50c11e80014fadee0f260', 2025, 0, 12, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 80 años, fumador. Refiere en los últimos días episodios de mareos no relacionados con el ejercicio ni el estrés, de unos 3-4 minutos de duración. Solicita atención urgente en su domicilio tras presentar un síncope, con pérdida completa de conciencia, de unos 15-20 segundos de duración. La presión arterial es 110/40 mmHg. Se obtiene el ECG de la imagen. ¿Cuál es su diagnóstico?:', '[{"position": 1, "text": "Infarto agudo de miocardio con elevación del segmento ST, anterior."}, {"position": 2, "text": "Bloqueo aurículo ventricular (AV) de primer grado."}, {"position": 3, "text": "Bloqueo AV de segundo grado, tipo II."}, {"position": 4, "text": "Bloqueo AV de tercer grado."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_12.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-013', '8cd97530c9e4b5dc2c0c88457e622a6a534c7a8b', 2025, 0, 13, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Hombre de 75 años que consulta por palpitaciones de aparición súbita hace 1 hora, sin dolor torácico ni cortejo vegetativo asociado. Tiene antecedentes de hipertensión arterial, dislipemia, hipertrofia benigna prostática y accidente isquémico transitorio hace 12 años. PA 180/109 mmHg, FC 126 lpm, Sat O2 98%. Auscultación cardíaca tonos rítmicos, sin soplos audibles. Miembros inferiores sin edemas ni signos de trombosis venosa profunda. Se realiza ECG que se muestra en la imagen. Indique, de los siguientes, el diagnóstico más probable:', '[{"position": 1, "text": "Fibrilación auricular."}, {"position": 2, "text": "Flutter auricular."}, {"position": 3, "text": "Infarto agudo de miocardio."}, {"position": 4, "text": "Taquicardia ventricular."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_13.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-014', '52b45a3488bc07b189be3402e11ad146aea3c4b7', 2025, 0, 14, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Mujer de 69 años, obesa, con historia de apnea obstructiva del sueño, insuficiencia respiratoria hipercápnica, polimialgia reumática e hipotiroidismo de larga evolución. Acude a consulta en su centro de salud con los resultados de una tomografía computarizada (TC) solicitada por hallazgo de cardiomegalia en la Rx de tórax. Su frecuencia cardíaca es 68 lpm, y la presión arterial es 145/70 mmHg. Con inspiración profunda, sus cifras tensionales son 139/68 mmHg. Con estos datos clínicos y la imagen de la TC que se muestra, señale qué diagnóstico es más probable:', '[{"position": 1, "text": "Neumotórax."}, {"position": 2, "text": "Taponamiento cardíaco con colapso de cavidades cardíacas."}, {"position": 3, "text": "Disección de aorta."}, {"position": 4, "text": "Derrame pericárdico crónico."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_14.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-015', 'f7be9992698a4de155a3e17fd0cedc860104b029', 2025, 0, 15, false, false, 'Nefrología', NULL, 'Paciente de 72 años con antecedentes de cardiopatía isquémica que acude a Urgencias por astenia, disnea de esfuerzo y malestar general desde hace dos semanas. En analítica se objetiva hemoglobina 7,1 g/dL, leucocitos 9.330/µL (Neutrófilos 77%), plaquetas 15.6000/µL, creatinina sérica 7,6 mg/dL (previa 1,1 mg/dL), Na+ 139 mmol/L, K+ 5,2 mmol/L. Orina: Na+ 121 mmol/L, K+ 21,3 mmol/L, cociente proteína/creatinina 3,5 g/g, eritrocitos +3, leucocitos +3. Se realiza un TC de tórax que se muestra en la imagen. Indique la actitud más correcta en relación con su diagnóstico y tratamiento inicial:', '[{"position": 1, "text": "Neumonía atípica con fracaso renal agudo secundario a necrosis tubular aguda y el tratamiento es la administración de antibióticos de amplio espectro y hemodiálisis."}, {"position": 2, "text": "Fracaso renal agudo parenquinatoso de probable origen glomerular con hemorragia alveolar asociada y el tratamiento es inmunosupresores y plasmaféresis."}, {"position": 3, "text": "Síndrome urémico hemolítico atípico y hay que plantear plasmaféresis y administración de eculizumab."}, {"position": 4, "text": "Fracaso renal agudo funcional secundario a insuficiencia cardíaca y hay que iniciar tratamiento con diuréticos a altas dosis y diálisis si no responde."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_15.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-016', 'b7849988e1e9fdadf73fa90ae471a5d9588f0cb9', 2025, 0, 16, false, false, 'Neumología y Cirugía Torácica', NULL, 'Hombre de 68 años, exfumador desde hace 3 meses, con criterios clínicos de bronquitis crónica. Consulta por cuadro de pérdida de peso junto con astenia de un mes y medio de duración. Refiere tos seca ocasional y sensación distérmica sin fiebre termometrada. Tras realizarle la radiografía de tórax se solicita TC torácico que se muestra en la imagen. ¿Cuál de los siguientes es el diagnóstico más probable?:', '[{"position": 1, "text": "Bronquiolitis respiratoria con enfermedad pulmonar intersticial."}, {"position": 2, "text": "Neumonía organizada criptogénica."}, {"position": 3, "text": "Atelectasia obstructiva de lóbulos inferiores por neoplasia central."}, {"position": 4, "text": "Neumonía intersticial inespecífica."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_16.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-017', '82aa1e2f25464f084e4ae4cf43d2ac60ddda9703', 2025, 0, 17, false, false, 'Aparato Digestivo', NULL, 'Paciente de 63 años consulta por dolor en flanco derecho, ictericia y aumento del perímetro abdominal. Se realiza ecografía doppler y TC de hígado como se muestra en la imagen. ¿Cuál de las siguientes es la mejor opción terapéutica?:', '[{"position": 1, "text": "Colocación de una derivación intrahepática percutánea (TIPS)."}, {"position": 2, "text": "Anticoagulación oral."}, {"position": 3, "text": "Trasplante hepático."}, {"position": 4, "text": "Angioplastia percutánea."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_17.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-018', '200f321552bb4e8c216ef74f52b654c89e6b7865', 2025, 0, 18, false, false, 'Aparato Digestivo', NULL, 'Mujer de 90 años que acude a urgencias por hipotensión, vómitos oscuros y dolor abdominal. Se realiza una TC abdominal que se muestra en la imagen. De las siguientes opciones, ¿cuál es la más probable?:', '[{"position": 1, "text": "Se observa gas en el sistema portal siendo indicativo de mal pronóstico."}, {"position": 2, "text": "Se trata de una aerobilia y por tanto el diagnóstico más probable es el de colangitis."}, {"position": 3, "text": "Se observa aerobilia y pneumatosis gástrica."}, {"position": 4, "text": "Se trata de un hallazgo no relevante en relación con una CPRE o cirugía previa."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_18.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-019', '4bd4bc49efecc5d55c2e7ee0b2e11df4c618c5e2', 2025, 0, 19, false, false, 'Aparato Digestivo', NULL, 'Hombre de 60 años sin antecedentes de interés que acude a urgencias con un cuadro de 48 horas de fiebre de 38°C y dolor abdominal en fosa ilíaca izquierda. A la exploración abdominal destaca cierta defensa a la palpación sin peritonismo generalizado. La analítica sanguínea sólo destaca una discreta leucocitosis. La TC abdomino-pélvica se muestra en la imagen adjunta. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Cáncer de colon izquierdo oclusivo."}, {"position": 2, "text": "Síndrome de Ogilvie."}, {"position": 3, "text": "Diverticulitis aguda."}, {"position": 4, "text": "Megacolon tóxico o infeccioso."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_19.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-020', '140a21290e3645a820cfe8d80e95d00ce9bf66fa', 2025, 0, 20, false, false, 'Urología', NULL, 'Hombre de 73 años con antecedentes de hipertensión arterial y diabetes mellitus tipo 2 que acude a urgencias por presentar desde hace una semana hiperglucemia mayor de 500 mg/dL. Refiere que comenzó con dolor en vacío derecho y vómitos autolimitados. Desde entonces, disminución de la ingesta, poliuria y sensación distérmica sin fiebre termometrada. Se realiza ecografía y TC abdominopélvica sin contraste intravenoso que se muestra en la imagen. ¿Cuál de los siguientes es el diagnóstico más probable?:', '[{"position": 1, "text": "Pielonefritis enfisematosa obstructiva."}, {"position": 2, "text": "Necrosis papilar renal."}, {"position": 3, "text": "Pielonefritis xantogranulomatosa."}, {"position": 4, "text": "Absceso retroperitoneal perirrenal por apendicitis aguda evolucionada."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_20.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-021', '0cb4df869f6c58825992584b196a36b4e5deac12', 2025, 0, 21, false, false, 'Hematología', NULL, 'Mujer de 57 años con enfermedad renal crónica que presenta astenia, hipotensión y cianosis en manos tras una sesión de diálisis. En la analítica se detecta anemia normocítica (Hb 7 g/dL, VCM 96 fL) con discreta reticulocitosis, leucocitos y plaquetas normales; aumento de LDH y hemoglobina libre en plasma elevada. El estudio inmunohematológico muestra un anticuerpo con especificidad anti-P. Se realiza frotis sanguíneo (ver imagen) mediante punción digital. El diagnóstico más probable es:', '[{"position": 1, "text": "Síndrome hemofagocítico."}, {"position": 2, "text": "Hemoglobinuria paroxística a frigore."}, {"position": 3, "text": "Hemoglobinuria paroxística nocturna."}, {"position": 4, "text": "Crioglobulinemia."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_21.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-022', 'd9d639363b9d19e4bdf760e311e4abede1e682c0', 2025, 0, 22, false, false, 'Reumatología', NULL, 'Mujer de 58 años acude a urgencias por dolor en la punta de los dedos de la mano. No tiene alergias conocidas, ni hábitos tóxicos. Entre los antecedentes explica tres abortos, una apendicetonría, sensación frecuente de reflujo retroesternal y, desde hace unos 5 años aproximadamente, presenta con la exposición al frío episodios de palidez en los dedos de ambas manos que cada vez se han hecho más intensos. A la vista de la imagen, ¿cuál de las siguientes actitudes se plantea realizar en primer lugar?:', '[{"position": 1, "text": "Solicitar una TC torácica."}, {"position": 2, "text": "Valoración de tratamiento quirúrgico por cirugía vascular."}, {"position": 3, "text": "Determinación de ANA y anti-centrómero."}, {"position": 4, "text": "Tratamiento vasodilatador con prostaglandinas iv."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_22.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-023', 'dfffbde28dc8de78835c0604ac16b1a5d9176a77', 2025, 0, 23, false, false, 'Neurología y Neurocirugía', NULL, 'En relación con un hombre de 74 años, que muestra alteraciones cognitivas y de la movilidad y en el cerebro neuronas con inclusiones citoplásmicas, como se observa en la imagen histológica, el diagnóstico más probable es:', '[{"position": 1, "text": "Enfermedad de Alzheimer."}, {"position": 2, "text": "Demencia senil."}, {"position": 3, "text": "Enfermedad de Parkinson."}, {"position": 4, "text": "Encefalitis viral."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_23.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-024', '329e3c458bb17ebd3ec31bf1972e4f997be83abd', 2025, 0, 24, false, false, 'Ginecología y Obstetricia', NULL, 'Mujer de 35 años con historia de dolor abdominal recurrente que coincide con la menstruación. Los hallazgos de la intervención quirúrgica requieren una resección intestinal. El estudio anatomopatológico se muestra en la imagen. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Adenocarcinoma intestinal."}, {"position": 2, "text": "Metástasis de adenocarcinoma de endometrio."}, {"position": 3, "text": "Colitis ulcerosa."}, {"position": 4, "text": "Endometriosis."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_24.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-025', 'f5f198a60cd2ab8d6493e4e4a4dc5a0eee58ed02', 2025, 0, 25, false, false, 'Enfermedades Infecciosas', NULL, 'Hombre de 36 años con prácticas sexuales de riesgo. Presenta un cuadro de 4 días de evolución de lesiones cutáneas no pruriginosas (ver imagen). No ha tomado medicación previamente y no tiene antecedente de alergias farmacológicas. Se realiza serología para VIH que es negativa. La serología de sífilis antiterponema pallidum es positiva y RPR 1:32. Señale la respuesta correcta:', '[{"position": 1, "text": "Se recomienda el análisis del líquido cefalorraquídeo."}, {"position": 2, "text": "La azitromicina oral es un tratamiento alternativo eficaz."}, {"position": 3, "text": "Se recomienda una valoración clínica y serológica (RPR) a los 6 y 12"}, {"position": 4, "text": "meses después del tratamiento.\n4. Si los títulos de RPR permanecen positivos después de 12 meses está indicado administrar el tratamiento de nuevo."}]'::jsonb, 4, NULL, NULL, NULL, true, 'images/25/image_25.png', true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-026', 'c5a101d4cb96c5aeaf7c9a7e57724ca99a2d7667', 2025, 0, 26, false, false, 'Endocrinología', NULL, 'Entre los cambios metabólicos que se observan en un paciente con resistencia a insulina existe:', '[{"position": 1, "text": "Incremento de la expresión hepática de genes gluconeogénicos mediado por FOXO1 (forkhead box other) fosforilado."}, {"position": 2, "text": "Descenso en los niveles intracelulares de hexoquinasa 2 dependiente de insulina."}, {"position": 3, "text": "Aumento de la glucogenólisis muscular, contribuyendo al incremento de la glucemia."}, {"position": 4, "text": "Aumento en los niveles séricos de aminoácidos como leucina e isoleucina."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-027', '01527d5e442f494fbfe083dac8850792dae2a3e0', 2025, 0, 27, false, false, 'Ciencias Básicas', NULL, 'La deficiencia de acil-CoA-deshidrogenasa provoca una de las siguientes alteraciones bioquímicas:', '[{"position": 1, "text": "Disminución de ácidos dicarboxílicos."}, {"position": 2, "text": "Aumento de la gluconeogénesis."}, {"position": 3, "text": "Disminución de la ureagénesis."}, {"position": 4, "text": "Aumento de carnitina libre."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-028', '95921651f88bffb9ab6a39d6b559d571b6eeb957', 2025, 0, 28, false, false, 'Oftalmología', NULL, 'Respecto a la técnica de exploración de la motilidad pupilar y sus reflejos indique la respuesta INCORRECTA:', '[{"position": 1, "text": "El reflejo de la visión próxima se explora con una linterna que se enfoca sobre las pupilas de forma alternativa."}, {"position": 2, "text": "El signo pupilar de Marcus Gunn o defecto pupilar aferente relativo está presente en enfermedades del nervio óptico y enfermedades retinianas no extensas."}, {"position": 3, "text": "El reflejo fotomotor consensuado está afectado cuando el daño implica la vía eferente vehiculada por el nervio motor ocular común."}, {"position": 4, "text": "La anisocoria que aumenta en condiciones de oscuridad mostrando una pupila más miótica se debe a que hay un trastorno en el sistema simpático."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-029', '11778aa116929fc0a8de4f842092b61c936e27b1', 2025, 0, 29, false, false, 'Geriatría', NULL, 'En relación con el proceso de envejecimiento, respecto a los principales cambios morfológicos de los aparatos y sistemas, indique la respuesta INCORRECTA:', '[{"position": 1, "text": "En el aparato respiratorio, calcificación de los cartílagos traqueales."}, {"position": 2, "text": "En el sistema nervioso, aumento del tamaño de los surcos interhemisféricos y de los ventriculos cerebrales."}, {"position": 3, "text": "En el aparato cardiovascular, reducción en el número de células marcapaso."}, {"position": 4, "text": "En el sistema nefrourológico, reducción del tejido mesangial."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-030', '9e392336b569516139390b45e262f81323770453', 2025, 0, 30, false, false, 'Ciencias Básicas', NULL, 'La utilización baja de energía por el músculo liso es fundamental para el gasto de energía corporal (órganos como los intestinos, la vejiga urinaria o la vesícula biliar mantienen una contracción muscular tónica casi indefinidamente). A este respecto, señale la afirmación correcta:', '[{"position": 1, "text": "La disposición física de los filamentos de miosina y actina es similar a la del músculo esquelético."}, {"position": 2, "text": "En esa contracción, es fundamental la lentitud de la unión y separación de los puentes cruzados entre los filamentos de actina y miosina."}, {"position": 3, "text": "La fuerza máxima de contracción es con frecuencia menor que la que se produce en el músculo esquelético."}, {"position": 4, "text": "La contracción prolongada exige que la excitación de las fibras musculares se mantenga mientras lo haga esa contracción."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-031', '3804ad083f9ddad6ae633f1edd5024baa06b48f3', 2025, 0, 31, false, false, 'Ciencias Básicas', NULL, 'En relación con el control químico de la respiración en condiciones fisiológicas señale la afirmación INCORRECTA:', '[{"position": 1, "text": "Los quimiorreceptores carotídeos y aórticos detectan especialmente cambios en la presión parcial de O2 en la sangre."}, {"position": 2, "text": "Los quimiorreceptores carotídeos y aórticos reciben un flujo arterial muy elevado por lo que se consideran expuestos en todo momento a sangre arterial."}, {"position": 3, "text": "Los quimiorreceptores centrales detectan fundamentalmente cambios en la concentración de H+ (procedente sobre todo de la disociación de CO2 y H2O)."}, {"position": 4, "text": "El efecto estimulador de la ventilación del CO2 se mantiene sin atenuación en los primeros días."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-032', 'fbf22a13f9528a0c5a89338f30adc25a79330569', 2025, 0, 32, false, false, 'Neurología y Neurocirugía', NULL, 'En un paciente diagnosticado de una neoplasia maligna de nasofaringe que presenta dolor y edema orbitario, neuropatía de los pares craneales III, IV y VI, y neuropatía de la rama V1 del V par craneal, indique qué estructura es más probable que se encuentre infiltrada:', '[{"position": 1, "text": "Seno cavernoso."}, {"position": 2, "text": "Hipófisis."}, {"position": 3, "text": "Agujero yugular."}, {"position": 4, "text": "Fosa pterigopalatina."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-033', '601a885779df2c66f6444ee8c2d27fd05076e782', 2025, 0, 33, false, false, 'Pediatría', NULL, 'Niña de 7 años con una sospecha de anemia de Fanconi. ¿Cuál de las siguientes manifestaciones clínicas NO se ajusta a los rasgos típicos de esta enfermedad?:', '[{"position": 1, "text": "Anomalías pigmentarias."}, {"position": 2, "text": "Anomalías renales."}, {"position": 3, "text": "Anomalías esqueléticas."}, {"position": 4, "text": "Estatura alta."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-034', '6f3671b981f9e84921a1af447022b60f1db88769', 2025, 0, 34, false, false, 'Genética e Inmunología', NULL, 'La exploración ecográfica de una mujer gestante de 26 semanas muestra hallazgos consistentes con osteogénesis imperfecta tipo II (gen COL1A1/COL1A2). La paciente tuvo un embarazo previo con la misma patología. Ni ella ni su pareja tienen manifestaciones clínicas de osteogénesis imperfecta. ¿Cuál de las siguientes es la explicación más probable para la recurrencia?:', '[{"position": 1, "text": "Herencia autosómica recesiva."}, {"position": 2, "text": "Mutación de novo."}, {"position": 3, "text": "Penetrancia incompleta."}, {"position": 4, "text": "Mosaicismo germinal."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-035', '696ef44ade9015da18b542bb8635be3028c9d65c', 2025, 0, 35, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'Las vacunas contra el neumococo recomendadas para prevenir la enfermedad neumocócica en personas mayores de 65 años y en pacientes inmunocomprometidos pueden estar constituidas por polisacáridos del neumococo purificados (PPV23) o polisacáridos conjugados a proteínas (PCV15 o PCV20). Desde una perspectiva inmunológica las vacunas conjugadas:', '[{"position": 1, "text": "No generan memoria inmunológica."}, {"position": 2, "text": "Activan una respuesta inmunitaria T-dependiente (o timo-dependiente)."}, {"position": 3, "text": "No activan el proceso de hipermutación somática."}, {"position": 4, "text": "No inducen cambio de isotipo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-036', 'f55bbdb03134d2e164b688936e9bd3edd9d86417', 2025, 0, 36, false, false, 'Genética e Inmunología', NULL, 'El paso de autoanticuerpos de la madre al feto a través de la placenta puede asociarse a la aparición de enfermedades autoinmunes en el recién nacido. Señale cuál de las parejas Enfermedad – Autoanticuerpo es INCORRECTA:', '[{"position": 1, "text": "Pénfigo vulgar – Anticuerpos antidesmogleina"}, {"position": 3, "text": "2. Bloqueo cardíaco congénito – Anticuerpos anti Ro y anti-La.\n3. Maistenia gravis – Anticuerpos anti receptor de la acetilcolina."}, {"position": 4, "text": "Lupus eritematoso neonatal – Anticuerpos anti-Sm."}]'::jsonb, 3, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-037', '1bc4cb4a80ac3be67585a410038e661483604885', 2025, 0, 37, false, false, 'Genética e Inmunología', NULL, 'Mutaciones en el gen Btk pueden causar una inmunodeficiencia primaria que cursa con la disminución drástica o ausencia de inmunoglobulinas en la sangre periférica (agammaglobulinemia). En relación al estudio de los pacientes con esta agammaglobulinemia, ¿cuál de las siguientes afirmaciones es cierta?', '[{"position": 1, "text": "Es una enfermedad autosómica recesiva."}, {"position": 2, "text": "El porcentaje de linfocitos que expresan CD19 o CD20 (linfocitos B) en sangre periférica está dentro de los límites normales."}, {"position": 3, "text": "El nivel de IgG en suero disminuye paulatinamente desde el nacimiento hasta resultar indetectable."}, {"position": 4, "text": "La expresión de la proteína Btk en monocitos es normal."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-038', 'a1ec9817b9004634d6cdb9c52d7427568bda6f0a', 2025, 0, 38, false, false, 'Alergología', NULL, 'Hombre de 20 años que, tras ingesta de gambas, presenta de forma prácticamente inmediata prurito palmoplantar, sensación de nudo en la garganta y ronquera, mareo, sensación de inestabilidad y debilidad intensa. Entre sus antecedentes destaca cuadro de edema laríngeo por alergia a las lentejas al año de edad. No refiere alergia conocida a otros alimentos, tampoco reacciones adversas a fármacos ni picadura de insectos. Entre los antecedentes familiares tiene un hermano con rinitis alérgica leve intermitente por alergia a pólenes. ¿Cuál debe ser el tratamiento inicial de forma urgente?:', '[{"position": 1, "text": "Hidrocortisona 500 mg IV y dexclorfeniramina 5 mg IV."}, {"position": 2, "text": "Adrenalina 0,3-0,5 mL IV."}, {"position": 3, "text": "Adrenalina 0,3-05 mL IM."}, {"position": 4, "text": "Metilprednisolona 40 mg IM y desclorfeniramina 5 mg IV."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-039', 'f6e94094bf24b4dd61bd9a6662539dbfc2e10414', 2025, 0, 39, false, false, 'Alergología', NULL, 'Hombre de 40 años sin antecedentes patológicos de interés, residente en una zona de interior de la península ibérica, que presentó cuadro de urticaria aguda por sensibilización a Anisakis simplex tras haber ingerido larvas vivas en unos boquerones en vinagre. El cuadro descrito le ocurrió hace más de 6 meses. Aporta prueba cutánea e IgE específica positiva frente a dicho parásito. En relación a la ingesta de pescados, ¿qué pauta de las que se indican a continuación debe seguir?:', '[{"position": 1, "text": "Puede comer pescados y mariscos sin ningún tipo de precaución dado que han transcurrido más de 6 meses de la ingesta."}, {"position": 2, "text": "No puede ingerir ningún tipo de pescado."}, {"position": 3, "text": "Puede comer pescado cocinado a 45ºC."}, {"position": 4, "text": "Puede comer pescado previamente congelado a -20ºC durante 72 horas en el domicilio o pescado congelado industrial."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2025-v0-040', '95bf3d7b7e9597664cda430ef973df1c750fcd6f', 2025, 0, 40, false, false, 'Medicina Preventiva y Epidemiología', NULL, 'La medida adecuada para estimar el riesgo individual de enfermar es:', '[{"position": 1, "text": "La incidencia acumulada."}, {"position": 2, "text": "La densidad de incidencia."}, {"position": 3, "text": "La prevalencia puntual."}, {"position": 4, "text": "El riesgo relativo."}]'::jsonb, 4, NULL, NULL, NULL, false, NULL, true, 'sin plantilla oficial de respuestas en la fuente', 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
